import type { Chord } from '../theory/chords.js';
import type { Key } from '../theory/keys.js';
import type { CadenceMatch } from '../theory/cadences.js';
import { scanCadences } from '../engine/cadence-detector.js';
import { type Circuit } from './session.js';

function randomId(): string {
  return Math.random().toString(36).slice(2, 10);
}

function buildNashvilleNotation(chords: Chord[], key: Key): string {
  return chords.map(chord => {
    const idx = key.scaleNotes.indexOf(chord.root);
    if (idx === -1) return chord.name;
    const degree = idx + 1;
    const isMinor = chord.quality === 'min' || chord.quality === 'min7';
    const isDim   = chord.quality === 'dim' || chord.quality === 'dim7';
    return `${degree}${isMinor ? 'm' : isDim ? '°' : ''}`;
  }).join('→');
}

export class CircuitTracker {
  private history: Chord[] = [];

  processNewChord(chord: Chord, key: Key): Circuit | null {
    if (this.history[this.history.length - 1]?.name === chord.name) return null;
    this.history = [...this.history, chord];

    const matches = scanCadences(this.history, key);

    // Find a resolving cadence that ends on the last chord
    const lastIdx = this.history.length - 1;
    const resolvingMatch = matches.find(
      m => m.pattern.tensionResolved && m.endIndex === lastIdx
    );

    if (!resolvingMatch) return null;

    // Circuit window = full accumulated history since last reset.
    // Must contain ≥ 3 unique chord roots.
    const uniqueRoots = new Set(this.history.map(c => c.root));
    if (uniqueRoots.size < 3) return null;

    const circuit: Circuit = {
      id:                randomId(),
      startIndex:        0,
      endIndex:          lastIdx,
      chords:            [...this.history],
      cadences:          matches,
      nashvilleNotation: buildNashvilleNotation(this.history, key),
      tensionResolved:   resolvingMatch.pattern.tensionResolved,
      completedAt:       Date.now(),
    };

    // Reset history so next phrase starts fresh
    this.history = [];

    return circuit;
  }

  getOpenCircuit(): Chord[] {
    return [...this.history];
  }

  reset(): void {
    this.history = [];
  }
}
