import type { Chord } from '../theory/chords.js';
import type { Key } from '../theory/keys.js';
import type { ModeName } from '../theory/modes.js';
import type { PitchClass } from '../theory/notes.js';
import type { Circuit } from '../session/session.js';
import type { KeyCandidate } from '../engine/key-inference.js';
import type { CadenceMatch } from '../theory/cadences.js';

export interface ChordGuess {
  chord: Chord;
  confidence: number;
}

export type AppEvent =
  | { type: 'chord:confirmed';   chord: Chord;              source: 'mic' | 'manual' }
  | { type: 'chord:pending';     guess: ChordGuess }
  | { type: 'chord:rejected' }
  | { type: 'key:candidate';     candidates: KeyCandidate[] }
  | { type: 'key:changed';       key: Key }
  | { type: 'key:dismissed' }
  | { type: 'circuit:completed'; circuit: Circuit }
  | { type: 'cadence:detected';  match: CadenceMatch }
  | { type: 'mode:changed';      mode: ModeName }
  | { type: 'pitch:detected'; frequency: number; pitchClass: PitchClass; octave: number; cents: number; confidence: number }
  | { type: 'audio:started' }
  | { type: 'audio:stopped' }
  | { type: 'session:reset' };

const bus = new EventTarget();

export function emit(event: AppEvent): void {
  bus.dispatchEvent(new CustomEvent(event.type, { detail: event }));
}

export function on<T extends AppEvent['type']>(
  type: T,
  handler: (event: Extract<AppEvent, { type: T }>) => void,
): void {
  bus.addEventListener(type, (e) => {
    handler((e as CustomEvent).detail as Extract<AppEvent, { type: T }>);
  });
}
