import { on } from './render.js';
import { getAnalyser, getSampleRate } from '../audio/mic-input.js';
import { qs } from './components.js';

const MIN_FREQ = 80;
const MAX_FREQ = 1318;
const DB_FLOOR = -90;
const DB_CEIL  = -10;

// Frequency band boundaries (Hz) mapped to harmonic color vars
const BAND_BOUNDARIES = [80, 246, 523, 880, 1318] as const;
const BAND_VARS = [
  '--color-subdominant', // 80–246 Hz:  bass/root strings
  '--color-tonic',       // 246–523 Hz: core chord tones
  '--color-dominant',    // 523–880 Hz: upper partials
  '--color-leading',     // 880–1318 Hz: high harmonics
] as const;

let container: HTMLElement;
let canvas: HTMLCanvasElement;
let ctx: CanvasRenderingContext2D;
let freqBuffer: Float32Array<ArrayBuffer> | null = null;
let rafId: number | null = null;
let isActive = false;

// Pre-computed per-frame layout (recomputed on resize)
let xPositions: Float32Array = new Float32Array(0);
let colorMap: Uint8Array = new Uint8Array(0);
let colors: [string, string, string, string] = ['', '', '', ''];
let minBin = 0;
let numBins = 0;

export function initAudioViz(): void {
  container = qs<HTMLElement>('#audio-viz');
  canvas    = qs<HTMLCanvasElement>('#viz-canvas');
  const maybeCtx = canvas.getContext('2d');
  if (!maybeCtx) return;
  ctx = maybeCtx;

  colors = BAND_VARS.map(v =>
    getComputedStyle(document.documentElement).getPropertyValue(v).trim()
  ) as [string, string, string, string];

  const ro = new ResizeObserver(() => { recomputeLayout(); });
  ro.observe(container);
  recomputeLayout();

  on('audio:started', () => { startViz(); });
  on('audio:stopped', () => { stopViz(); });
}

function recomputeLayout(): void {
  const dpr = window.devicePixelRatio || 1;
  const w   = container.clientWidth;
  const h   = container.clientHeight;
  canvas.width  = Math.round(w * dpr);
  canvas.height = Math.round(h * dpr);
  ctx.scale(dpr, dpr);

  const analyser = getAnalyser();
  const sr = analyser ? getSampleRate() : 44100;
  const fftSize = analyser ? analyser.fftSize : 8192;
  const hzPerBin = sr / fftSize;

  minBin = Math.ceil(MIN_FREQ / hzPerBin);
  const maxBin = Math.floor(MAX_FREQ / hzPerBin);
  numBins = maxBin - minBin;

  const logMin = Math.log(MIN_FREQ);
  const logMax = Math.log(MAX_FREQ);

  xPositions = new Float32Array(numBins + 1);
  colorMap   = new Uint8Array(numBins);

  for (let i = 0; i <= numBins; i++) {
    const hz = (minBin + i) * hzPerBin;
    const t  = (Math.log(hz) - logMin) / (logMax - logMin);
    xPositions[i] = t * w;
  }

  for (let i = 0; i < numBins; i++) {
    const hz = (minBin + i) * hzPerBin;
    let band = 0;
    for (let b = 1; b < BAND_BOUNDARIES.length - 1; b++) {
      const boundary = BAND_BOUNDARIES[b];
      if (boundary !== undefined && hz >= boundary) band = b;
    }
    colorMap[i] = band;
  }

  if (freqBuffer === null && analyser) {
    freqBuffer = new Float32Array(analyser.frequencyBinCount);
  }
}

function startViz(): void {
  const analyser = getAnalyser();
  if (!analyser) return;

  if (freqBuffer === null || freqBuffer.length !== analyser.frequencyBinCount) {
    freqBuffer = new Float32Array(analyser.frequencyBinCount);
  }

  container.classList.add('active');
  isActive = true;
  if (rafId === null) {
    rafId = requestAnimationFrame(rafLoop);
  }
}

function stopViz(): void {
  isActive = false;
  container.classList.remove('active');
  if (rafId !== null) {
    cancelAnimationFrame(rafId);
    rafId = null;
  }
  ctx.clearRect(0, 0, canvas.width, canvas.height);
}

function rafLoop(): void {
  if (!isActive) { rafId = null; return; }

  const analyser = getAnalyser();
  if (!analyser || !freqBuffer) { rafId = null; return; }

  analyser.getFloatFrequencyData(freqBuffer);
  drawFrame();
  rafId = requestAnimationFrame(rafLoop);
}

function drawFrame(): void {
  if (!freqBuffer) return;
  const w = canvas.width / (window.devicePixelRatio || 1);
  const h = canvas.height / (window.devicePixelRatio || 1);

  ctx.clearRect(0, 0, w, h);

  for (let i = 0; i < numBins; i++) {
    const db   = freqBuffer[minBin + i] ?? DB_FLOOR;
    const t    = Math.max(0, Math.min(1, (db - DB_FLOOR) / (DB_CEIL - DB_FLOOR)));
    const barH = t * h;
    if (barH < 0.5) continue;

    const x1 = xPositions[i] ?? 0;
    const x2 = (xPositions[i + 1] ?? x1 + 1) - 1;
    const bw  = Math.max(1, x2 - x1);

    ctx.fillStyle = colors[colorMap[i] ?? 0] ?? '';
    ctx.fillRect(x1, h - barH, bw, barH);
  }
}
