import type { PitchClass } from "../theory/notes.js";

export interface PitchResult {
  frequency: number;
  confidence: number;
  pitchClass: PitchClass;
  octave: number;
}

const MIN_FREQ = 80;
// const MAX_FREQ = 1318;
const MAX_FREQ = 500;
const THRESHOLD_DB = -60;

function freqToPitchClass(freq: number): {
  pitchClass: PitchClass;
  octave: number;
} {
  const midi = 12 * Math.log2(freq / 440) + 69;
  const rounded = Math.round(midi);
  const octave = Math.floor(rounded / 12) - 1;
  const pc = (((rounded % 12) + 12) % 12) as PitchClass;
  return { pitchClass: pc, octave };
}

export function detectPitches(
  analyser: AnalyserNode,
  sampleRate: number,
): PitchResult[] {
  const bufLen = analyser.fftSize;
  const binCount = analyser.frequencyBinCount;
  const hzPerBin = sampleRate / bufLen;

  const freqData = new Float32Array(binCount);
  analyser.getFloatFrequencyData(freqData);

  const minBin = Math.max(1, Math.ceil(MIN_FREQ / hzPerBin));
  const maxBin = Math.min(binCount - 2, Math.floor(MAX_FREQ / hzPerBin));

  // Find local maxima above threshold
  const peaks: { bin: number; db: number }[] = [];
  for (let i = minBin; i <= maxBin; i++) {
    const db = freqData[i] ?? -200;
    if (
      db > THRESHOLD_DB &&
      db >= (freqData[i - 1] ?? -200) &&
      db >= (freqData[i + 1] ?? -200)
    ) {
      peaks.push({ bin: i, db });
    }
  }

  peaks.sort((a, b) => b.db - a.db);

  // Harmonic filter: suppress peaks that are 2nd or 3rd harmonics of a stronger peak
  const fundamentals: { bin: number; db: number }[] = [];
  outer: for (const peak of peaks) {
    const freq = peak.bin * hzPerBin;
    for (const f of fundamentals) {
      const fFreq = f.bin * hzPerBin;
      for (const n of [2, 3]) {
        if (Math.abs(freq - fFreq * n) / (fFreq * n) < 0.04) continue outer;
      }
    }
    fundamentals.push(peak);
  }

  // YIN on time-domain buffer for refined primary fundamental
  const timeData = new Float32Array(bufLen);
  analyser.getFloatTimeDomainData(timeData);
  const yin = yinPitch(timeData, sampleRate);

  const results: PitchResult[] = [];

  if (yin && yin.confidence > 0.6) {
    const { pitchClass, octave } = freqToPitchClass(yin.frequency);
    results.push({
      frequency: yin.frequency,
      confidence: yin.confidence,
      pitchClass,
      octave,
    });
  }

  // Add FFT fundamentals not already covered by YIN result
  for (const f of fundamentals.slice(0, 6)) {
    const freq = f.bin * hzPerBin;
    const { pitchClass, octave } = freqToPitchClass(freq);
    if (results.some((r) => r.pitchClass === pitchClass)) continue;
    // Normalize dB to confidence: -60 dBFS → 0, 0 dBFS → 1
    const conf = Math.max(
      0,
      Math.min(1, (f.db - THRESHOLD_DB) / -THRESHOLD_DB),
    );
    if (conf >= 0.3) {
      results.push({ frequency: freq, confidence: conf, pitchClass, octave });
    }
  }

  return results;
}

// YIN pitch detection — monophonic fundamental estimator used to refine primary pitch.
// Only searches the guitar frequency range to bound O(n²) cost.
function yinPitch(
  buf: Float32Array,
  sampleRate: number,
): { frequency: number; confidence: number } | null {
  const halfN = Math.min(2048, Math.floor(buf.length / 2));
  const minTau = Math.max(2, Math.floor(sampleRate / MAX_FREQ));
  const maxTau = Math.min(halfN - 1, Math.ceil(sampleRate / MIN_FREQ));

  // Difference function
  const diff = new Float32Array(maxTau + 1);
  for (let tau = 1; tau <= maxTau; tau++) {
    let sum = 0;
    for (let i = 0; i < halfN; i++) {
      const d = (buf[i] ?? 0) - (buf[i + tau] ?? 0);
      sum += d * d;
    }
    diff[tau] = sum;
  }

  // Cumulative mean normalized difference
  const cmndf = new Float32Array(maxTau + 1);
  cmndf[0] = 1;
  let runningSum = 0;
  for (let tau = 1; tau <= maxTau; tau++) {
    runningSum += diff[tau] ?? 0;
    cmndf[tau] = runningSum > 0 ? ((diff[tau] ?? 0) * tau) / runningSum : 0;
  }

  // Find first dip below threshold in guitar range
  const THRESHOLD = 0.15;
  let tau = -1;
  for (let t = minTau; t < maxTau; t++) {
    if ((cmndf[t] ?? 1) < THRESHOLD) {
      while (t + 1 <= maxTau && (cmndf[t + 1] ?? 1) < (cmndf[t] ?? 1)) t++;
      tau = t;
      break;
    }
  }
  if (tau === -1) return null;

  // Parabolic interpolation for sub-sample accuracy
  let betterTau = tau;
  if (tau > minTau && tau < maxTau) {
    const s0 = cmndf[tau - 1] ?? 1;
    const s1 = cmndf[tau] ?? 1;
    const s2 = cmndf[tau + 1] ?? 1;
    const denom = 2 * s1 - s2 - s0;
    if (Math.abs(denom) > 1e-6) {
      betterTau = tau + (s2 - s0) / (2 * denom);
    }
  }

  const frequency = sampleRate / betterTau;
  if (frequency < MIN_FREQ || frequency > MAX_FREQ) return null;

  return { frequency, confidence: 1 - (cmndf[tau] ?? 1) };
}
