import type { PitchClass } from './notes.js';
import { noteName } from './notes.js';

export type ChordQuality = 'maj'|'min'|'dom7'|'maj7'|'min7'|'dim'|'dim7'|'sus2'|'sus4'|'min7b5';
export type ChordColor   = 'warm-gold'|'orange'|'cool-blue'|'purple'|'green'|'neutral';

// Intervals in semitones from root
export const CHORD_INTERVALS: Record<ChordQuality, number[]> = {
  maj:    [0, 4, 7],
  min:    [0, 3, 7],
  dom7:   [0, 4, 7, 10],
  maj7:   [0, 4, 7, 11],
  min7:   [0, 3, 7, 10],
  dim:    [0, 3, 6],
  dim7:   [0, 3, 6, 9],
  sus2:   [0, 2, 7],
  sus4:   [0, 5, 7],
  min7b5: [0, 3, 6, 10],
};

export const QUALITY_SUFFIX: Record<ChordQuality, string> = {
  maj:    '',
  min:    'm',
  dom7:   '7',
  maj7:   'maj7',
  min7:   'm7',
  dim:    '°',
  dim7:   '°7',
  sus2:   'sus2',
  sus4:   'sus4',
  min7b5: 'ø7',
};

export const MOOD_WORDS: Record<ChordColor, string> = {
  'warm-gold':  'Tonic',
  'orange':     'Dominant',
  'cool-blue':  'Pre-dominant',
  'green':      'Color',
  'purple':     'Leading tone',
  'neutral':    'Chromatic',
};

export interface Chord {
  root:             PitchClass;
  quality:          ChordQuality;
  name:             string;
  nashvilleNumeral: string;
  nashvilleIndex:   number;
  color:            ChordColor;
  moodWord:         string;
  pitchClasses:     PitchClass[];
}

export function buildChord(
  root: PitchClass,
  quality: ChordQuality,
  preferFlats = false,
  nashvilleNumeral = '',
  nashvilleIndex = 0,
  color: ChordColor = 'neutral',
): Chord {
  const intervals = CHORD_INTERVALS[quality];
  const pitchClasses = intervals.map(i => ((root + i) % 12) as PitchClass);
  const rootName = noteName(root, preferFlats);
  const name = rootName + QUALITY_SUFFIX[quality];
  const moodWord = MOOD_WORDS[color];
  return { root, quality, name, nashvilleNumeral, nashvilleIndex, color, moodWord, pitchClasses };
}
