import { emit, on } from './render.js';
import { el, patchText, qs } from './components.js';
import { stopGamePanel } from './game-panel.js';
import { generateTab } from '../engine/tab-generator.js';
import type { ModeName } from '../theory/modes.js';
import { NOTE_NAMES_SHARP } from '../theory/notes.js';
import type { Key } from '../theory/keys.js';
import type { PitchClass } from '../theory/notes.js';

const MODE_NAMES: ModeName[] = ['Ionian', 'Dorian', 'Phrygian', 'Lydian', 'Mixolydian', 'Aeolian', 'Locrian'];

// Standard tuning: E2 A2 D3 G3 B3 E4
const STRINGS: { label: string; pitchClass: PitchClass; octave: number }[] = [
  { label: 'E₂', pitchClass: 4, octave: 2 },
  { label: 'A₂', pitchClass: 9, octave: 2 },
  { label: 'D₃', pitchClass: 2, octave: 3 },
  { label: 'G₃', pitchClass: 7, octave: 3 },
  { label: 'B₃', pitchClass: 11, octave: 3 },
  { label: 'E₄', pitchClass: 4, octave: 4 },
];

let tabDisplay: HTMLPreElement;
let activeMode: ModeName = 'Ionian';
let currentKey: Key | null = null;
const modeTabBtns = new Map<ModeName, HTMLButtonElement>();

// Tuner state
let tunerActive = false;
let audioActive = false;
let tunerBtn: HTMLButtonElement | null = null;

// Game tab state
let gameTabBtn: HTMLButtonElement | null = null;
let tunerWrap: HTMLElement | null = null;
let tunerNoteEl: HTMLElement | null = null;
let tunerCentsEl: HTMLElement | null = null;
let tunerNeedle: HTMLElement | null = null;
let tunerStringChips: HTMLElement[] = [];

function midiNote(pitchClass: PitchClass, octave: number): number {
  return (octave + 1) * 12 + pitchClass;
}

function nearestStringIdx(pitchClass: PitchClass, octave: number): number {
  const detectedMidi = midiNote(pitchClass, octave);
  let bestIdx = 0;
  let bestDist = Infinity;
  for (let i = 0; i < STRINGS.length; i++) {
    const s = STRINGS[i];
    if (!s) continue;
    const dist = Math.abs(detectedMidi - midiNote(s.pitchClass, s.octave));
    if (dist < bestDist) { bestDist = dist; bestIdx = i; }
  }
  return bestIdx;
}

function renderTuner(panel: HTMLElement): void {
  tunerWrap = el('div', { class: 'tuner-wrap' });

  // Top row: note + cents
  const topRow = el('div', { class: 'tuner-top-row' });
  tunerNoteEl = el('div', { class: 'tuner-note' }, audioActive ? '–' : '–');
  tunerCentsEl = el('div', { class: 'tuner-cents' }, '');
  topRow.append(tunerNoteEl, tunerCentsEl);

  // Track + needle
  const trackWrap = el('div', { class: 'tuner-track-wrap' });
  const trackLabels = el('div', { class: 'tuner-track-labels' });
  trackLabels.append(
    el('span', {}, '−50¢'),
    el('span', {}, '0'),
    el('span', {}, '+50¢'),
  );
  const track = el('div', { class: 'tuner-track' });
  tunerNeedle = el('div', { class: 'tuner-needle' });
  track.append(tunerNeedle);
  trackWrap.append(track, trackLabels);

  // String chips
  const stringsRow = el('div', { class: 'tuner-strings' });
  tunerStringChips = [];
  for (const s of STRINGS) {
    const chip = el('div', { class: 'tuner-string-chip' }, s.label);
    tunerStringChips.push(chip);
    stringsRow.append(chip);
  }

  tunerWrap.append(topRow, trackWrap, stringsRow);
  panel.append(tunerWrap);

  // Reset to idle state
  setTunerIdle();
}

function setTunerIdle(): void {
  if (!tunerNoteEl || !tunerCentsEl || !tunerNeedle) return;
  tunerNoteEl.textContent = '–';
  tunerNoteEl.className = 'tuner-note';
  tunerCentsEl.textContent = '';
  tunerNeedle.style.left = '50%';
  tunerNeedle.className = 'tuner-needle';
  for (const chip of tunerStringChips) chip.classList.remove('active');
}

function updateTuner(pitchClass: PitchClass, octave: number, cents: number): void {
  if (!tunerNoteEl || !tunerCentsEl || !tunerNeedle) return;

  const noteName = NOTE_NAMES_SHARP[pitchClass] ?? '?';
  tunerNoteEl.textContent = `${noteName}${octave}`;

  const sign = cents >= 0 ? '+' : '';
  tunerCentsEl.textContent = `${sign}${cents}¢`;

  const absCents = Math.abs(cents);
  const tuneClass = absCents <= 5 ? 'in-tune' : absCents <= 20 ? 'close' : 'off';
  tunerNoteEl.className = `tuner-note ${tuneClass}`;
  tunerCentsEl.className = `tuner-cents ${tuneClass}`;
  tunerNeedle.className = `tuner-needle ${tuneClass}`;

  const pct = 50 + Math.max(-50, Math.min(50, cents));
  tunerNeedle.style.left = `${pct}%`;

  const nearIdx = nearestStringIdx(pitchClass, octave);
  for (let i = 0; i < tunerStringChips.length; i++) {
    tunerStringChips[i]?.classList.toggle('active', i === nearIdx);
  }
}

function renderPanelContent(panel: HTMLElement): void {
  // Remove previous content area (everything after the tab bar)
  while (panel.children.length > 1) panel.removeChild(panel.lastChild!);
  tunerWrap = null;
  tunerNoteEl = null;
  tunerCentsEl = null;
  tunerNeedle = null;
  tunerStringChips = [];

  if (tunerActive) {
    renderTuner(panel);
  } else {
    tabDisplay = el('pre', { class: 'tab-display' }) as HTMLPreElement;
    panel.append(tabDisplay);
    renderTab();
  }
}

export function initModesPanel(): void {
  const panel = qs<HTMLElement>('#modes-panel');
  const gamePanel = qs<HTMLElement>('#game-panel');
  panel.innerHTML = '';

  let gameTabActive = false;

  const tabBar = el('div', { class: 'mode-tab-bar' });

  for (const mode of MODE_NAMES) {
    const btn = el('button', {
      class: `mode-tab-btn${mode === activeMode ? ' active' : ''}`,
    }, mode) as HTMLButtonElement;
    btn.addEventListener('click', () => {
      if (gameTabActive) {
        gameTabActive = false;
        gameTabBtn?.classList.remove('active');
        gamePanel.classList.add('hidden');
      }
      if (tunerActive) {
        tunerActive = false;
        if (tunerBtn) tunerBtn.classList.remove('active');
        renderPanelContent(panel);
      }
      emit({ type: 'mode:changed', mode });
    });
    modeTabBtns.set(mode, btn);
    tabBar.append(btn);
  }

  tunerBtn = el('button', { class: 'mode-tab-btn tuner-tab-btn' }, '♩ Tuner') as HTMLButtonElement;
  tunerBtn.addEventListener('click', () => {
    if (gameTabActive) {
      gameTabActive = false;
      gameTabBtn?.classList.remove('active');
      gamePanel.classList.add('hidden');
    }
    tunerActive = !tunerActive;
    tunerBtn!.classList.toggle('active', tunerActive);
    // Deactivate mode tabs when tuner is on
    if (tunerActive) {
      for (const btn of modeTabBtns.values()) btn.classList.remove('active');
    } else {
      modeTabBtns.get(activeMode)?.classList.add('active');
    }
    renderPanelContent(panel);
  });
  tabBar.append(tunerBtn);

  gameTabBtn = el('button', { class: 'mode-tab-btn game-tab-btn' }, '⚔ Game') as HTMLButtonElement;
  gameTabBtn.addEventListener('click', () => {
    gameTabActive = !gameTabActive;
    gameTabBtn!.classList.toggle('active', gameTabActive);
    if (gameTabActive) {
      if (tunerActive) {
        tunerActive = false;
        tunerBtn?.classList.remove('active');
      }
      for (const btn of modeTabBtns.values()) btn.classList.remove('active');
      gamePanel.classList.remove('hidden');
    } else {
      stopGamePanel();
      gamePanel.classList.add('hidden');
      if (!tunerActive) modeTabBtns.get(activeMode)?.classList.add('active');
      renderPanelContent(panel);
    }
  });
  tabBar.append(gameTabBtn);

  panel.append(tabBar);

  tabDisplay = el('pre', { class: 'tab-display' }, 'Select a key to see mode tablature') as HTMLPreElement;
  panel.append(tabDisplay);

  on('key:changed', (event) => {
    currentKey = event.key;
    const defaultMode: ModeName = event.key.mode === 'minor' ? 'Aeolian' : 'Ionian';
    if (activeMode !== defaultMode) {
      const prev = modeTabBtns.get(activeMode);
      if (prev) prev.classList.remove('active');
      activeMode = defaultMode;
      const next = modeTabBtns.get(activeMode);
      if (next && !tunerActive) next.classList.add('active');
    }
    if (!tunerActive) renderTab();
  });

  on('mode:changed', (event) => {
    const prev = modeTabBtns.get(activeMode);
    if (prev) prev.classList.remove('active');
    activeMode = event.mode;
    const next = modeTabBtns.get(activeMode);
    if (next) next.classList.add('active');
    if (!tunerActive) renderTab();
  });

  on('audio:started', () => {
    audioActive = true;
  });

  on('audio:stopped', () => {
    audioActive = false;
    if (tunerActive) setTunerIdle();
  });

  on('pitch:detected', (event) => {
    if (!tunerActive) return;
    updateTuner(event.pitchClass, event.octave, event.cents);
  });

  on('session:reset', () => {
    if (tunerActive) setTunerIdle();
  });
}

function renderTab(): void {
  if (!tabDisplay) return;
  if (!currentKey) {
    patchText(tabDisplay, 'Select a key to see mode tablature');
    return;
  }
  patchText(tabDisplay, generateTab(currentKey, activeMode));
}

export { activeMode };
