import type { Key } from '../theory/keys.js';
import { getModeRoot, buildModeScale, MODES, type ModeName } from '../theory/modes.js';
import type { PitchClass } from '../theory/notes.js';

export type TabString = string;

// String labels top-to-bottom (high e → low E) as displayed in tab notation
const STRING_LABELS = ['e', 'B', 'G', 'D', 'A', 'E'] as const;

// Open pitch class for strings 1–6 (index 0 = string 1 = high e)
const OPEN_PC: PitchClass[] = [4, 11, 7, 2, 9, 4];

export function generateTab(key: Key, mode: ModeName): TabString {
  const modeData = MODES[mode];
  const modeRoot = getModeRoot(key, mode);
  const modeScale = buildModeScale(modeRoot, modeData.intervals);
  const scalePCSet = new Set<PitchClass>(modeScale);

  const tonicName = key.name.split(' ')[0] ?? '';
  const header = `${tonicName} ${mode} — ${modeData.character}`;

  const lines = STRING_LABELS.map((label, i) => {
    const openPC = OPEN_PC[i] as PitchClass;
    const frets: number[] = [];
    for (let fret = 0; fret <= 12; fret++) {
      const pc = ((openPC + fret) % 12) as PitchClass;
      if (scalePCSet.has(pc)) {
        frets.push(fret);
      }
    }
    const noteStr = frets.map(f => f < 10 ? `-${f}` : `${f}`).join('-');
    return `${label}|--${noteStr}--|`;
  });

  return [header, ...lines].join('\n');
}
