import { on } from './render.js';
import { qs } from './components.js';
import type { Chord, ChordColor } from '../theory/chords.js';
import type { Key } from '../theory/keys.js';
import type { PitchClass } from '../theory/notes.js';
import { NOTE_NAMES_SHARP } from '../theory/notes.js';

// ── Types ─────────────────────────────────────────────────────────────────

interface Ring {
  color:          string;
  radius:         number;
  maxRadius:      number;
  initialOpacity: number;
  strokeWidth:    number;
  expandRate:     number;
}

type RGB = [number, number, number];

// ── Constants ─────────────────────────────────────────────────────────────

const MAX_RINGS        = 20;
const RING_POINTS      = 80;
const RINGS_PER_CHORD  = 2;

// Resolved at init from CSS vars; hardcoded values are exact fallbacks
const COLOR_HEX: Record<ChordColor, string> = {
  'warm-gold':  '#c49a14',
  'orange':     '#d4621a',
  'cool-blue':  '#3a72b8',
  'green':      '#2d8a40',
  'purple':     '#7b3aab',
  'neutral':    '#666680',
};

const COLOR_RGB: Record<ChordColor, RGB> = {
  'warm-gold':  [196, 154,  20],
  'orange':     [212,  98,  26],
  'cool-blue':  [ 58, 114, 184],
  'green':      [ 45, 138,  64],
  'purple':     [123,  58, 171],
  'neutral':    [102, 102, 128],
};

// Harmonic tension score [0,1] used to size rings
const COLOR_TENSION: Record<ChordColor, number> = {
  'warm-gold':  0.05,
  'cool-blue':  0.40,
  'green':      0.30,
  'orange':     0.85,
  'purple':     0.95,
  'neutral':    0.50,
};

// ── Module state ──────────────────────────────────────────────────────────

let screen: HTMLElement;
let canvas: HTMLCanvasElement;
let ctx:    CanvasRenderingContext2D;
let vizBtn: HTMLButtonElement;

let active        = false;
let rafId: number | null = null;
let theoryDepth: 1 | 2 | 3 = 1;
let shimmerAmount  = 0;
let startTime      = 0;

let rings:        Ring[]        = [];
let currentChord: Chord | null  = null;
let currentKey:   Key   | null  = null;
let bgTarget:     RGB           = [0, 0, 0];
let bgCurrent:    RGB           = [0, 0, 0];

// ── Init ──────────────────────────────────────────────────────────────────

export function initVisualizer(): void {
  screen  = qs<HTMLElement>('#viz-screen');
  canvas  = qs<HTMLCanvasElement>('#aurora-canvas');
  vizBtn  = qs<HTMLButtonElement>('#viz-toggle-btn');

  const maybeCtx = canvas.getContext('2d');
  if (!maybeCtx) return;
  ctx = maybeCtx;

  // Override hardcoded colors with resolved CSS variable values
  const style = getComputedStyle(document.documentElement);
  const CSS_VAR_MAP: [ChordColor, string][] = [
    ['warm-gold',  '--color-tonic'],
    ['orange',     '--color-dominant'],
    ['cool-blue',  '--color-subdominant'],
    ['green',      '--color-mediant'],
    ['purple',     '--color-leading'],
    ['neutral',    '--color-chromatic'],
  ];
  for (const [key, varName] of CSS_VAR_MAP) {
    const val = style.getPropertyValue(varName).trim();
    if (val) COLOR_HEX[key] = val;
  }

  // Depth dial
  screen.querySelectorAll<HTMLButtonElement>('.viz-depth-btn').forEach(btn => {
    btn.addEventListener('click', () => {
      const d = parseInt(btn.dataset['depth'] ?? '1', 10);
      if (d === 1 || d === 2 || d === 3) {
        theoryDepth = d;
        screen.querySelectorAll<HTMLButtonElement>('.viz-depth-btn')
          .forEach(b => b.classList.toggle('active', b === btn));
      }
    });
  });

  vizBtn.addEventListener('click', enter);
  qs<HTMLButtonElement>('#viz-back-btn').addEventListener('click', exit);
  document.addEventListener('keydown', (e) => { if (e.key === 'Escape' && active) exit(); });

  // Resize canvas when screen becomes visible or viewport changes
  const ro = new ResizeObserver(() => { if (active) resizeCanvas(); });
  ro.observe(screen);

  // Event subscriptions
  on('chord:confirmed', (e) => {
    currentChord = e.chord;
    spawnRing(e.chord);
    bgTarget = [...(COLOR_RGB[e.chord.color] ?? ([0, 0, 0] as RGB))] as RGB;
  });
  on('pitch:detected',    (e) => { shimmerAmount = e.confidence; });
  on('circuit:completed', ()  => { bloomAllRings(); });
  on('key:changed',       (e) => { currentKey = e.key; });
  on('session:reset',     ()  => {
    rings         = [];
    currentChord  = null;
    currentKey    = null;
    shimmerAmount = 0;
    bgTarget   = [0, 0, 0];
    bgCurrent  = [0, 0, 0];
  });
}

// ── Enter / Exit ──────────────────────────────────────────────────────────

function enter(): void {
  active = true;
  screen.classList.add('active');
  vizBtn.classList.add('active');
  startTime = performance.now();
  // ResizeObserver fires on visibility change; start loop after first resize
  requestAnimationFrame(() => {
    resizeCanvas();
    if (rafId === null) rafId = requestAnimationFrame(rafLoop);
  });
}

function exit(): void {
  active = false;
  screen.classList.remove('active');
  vizBtn.classList.remove('active');
  if (rafId !== null) { cancelAnimationFrame(rafId); rafId = null; }
}

// ── Canvas ────────────────────────────────────────────────────────────────

function resizeCanvas(): void {
  const dpr = window.devicePixelRatio || 1;
  const w = canvas.clientWidth;
  const h = canvas.clientHeight;
  if (w === 0 || h === 0) return;
  canvas.width  = Math.round(w * dpr);
  canvas.height = Math.round(h * dpr);
}

// ── Rings ─────────────────────────────────────────────────────────────────

function spawnRing(chord: Chord): void {
  const dpr     = window.devicePixelRatio || 1;
  const w       = canvas.width  / dpr;
  const h       = canvas.height / dpr;
  // Reach the farthest corner so rings always fill the screen
  const corner  = Math.sqrt((w / 2) ** 2 + (h / 2) ** 2);
  const tension = COLOR_TENSION[chord.color] ?? 0.5;
  const color   = COLOR_HEX[chord.color] ?? '#666680';

  for (let i = 0; i < RINGS_PER_CHORD; i++) {
    if (rings.length >= MAX_RINGS) rings.shift();
    // Stagger starting radii so they look like concentric ripples in motion
    const startProgress = i * 0.07;
    rings.push({
      color,
      radius:         corner * startProgress,
      maxRadius:      corner,
      initialOpacity: 0.88 - i * 0.10,
      strokeWidth:    2.8 + tension * 3.2 - i * 0.45,
      expandRate:     0.007 + tension * 0.0025,
    });
  }
}

function bloomAllRings(): void {
  for (const ring of rings) {
    ring.initialOpacity = Math.min(1.0, ring.initialOpacity * 1.4);
    ring.expandRate     = 0.016;
  }
}

// ── Shimmer ───────────────────────────────────────────────────────────────

function shimmerOffset(angle: number, t: number, amp: number): number {
  return amp * (
    Math.sin(angle * 3  + t * 2.1) * 0.5 +
    Math.sin(angle * 7  + t * 1.3) * 0.3 +
    Math.sin(angle * 13 + t * 0.7) * 0.2
  );
}

// ── RAF Loop ──────────────────────────────────────────────────────────────

function rafLoop(): void {
  if (!active) { rafId = null; return; }
  renderFrame();
  rafId = requestAnimationFrame(rafLoop);
}

function renderFrame(): void {
  const dpr = window.devicePixelRatio || 1;
  const w   = canvas.width  / dpr;
  const h   = canvas.height / dpr;
  if (w === 0 || h === 0) return;

  const cx = w / 2;
  const cy = h / 2;
  const t  = (performance.now() - startTime) / 1000;

  // Lerp background toward current chord color at low saturation
  const [r0, g0, b0] = bgCurrent;
  const [rt, gt, bt] = bgTarget;
  bgCurrent = [
    r0 + (rt - r0) * 0.015,
    g0 + (gt - g0) * 0.015,
    b0 + (bt - b0) * 0.015,
  ];

  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);

  // Dark background with faint harmonic tint
  const [rc, gc, bc] = bgCurrent;
  ctx.fillStyle = `rgb(${Math.round(13 + rc * 0.10)},${Math.round(13 + gc * 0.07)},${Math.round(18 + bc * 0.10)})`;
  ctx.fillRect(0, 0, w, h);

  // Draw rings back-to-front (oldest first)
  for (let ri = rings.length - 1; ri >= 0; ri--) {
    const ring = rings[ri];
    if (!ring) continue;

    ring.radius = Math.min(ring.maxRadius, ring.radius + ring.maxRadius * ring.expandRate);
    const progress = ring.radius / ring.maxRadius;
    // Ease out: bright at spawn, fully transparent at edge
    const opacity = ring.initialOpacity * Math.pow(1 - progress, 1.4);
    if (opacity <= 0.008) { rings.splice(ri, 1); continue; }

    ctx.save();
    ctx.globalAlpha = opacity;
    ctx.strokeStyle = ring.color;
    ctx.lineWidth   = ring.strokeWidth;
    ctx.shadowBlur  = 22;
    ctx.shadowColor = ring.color;

    // Scale shimmer with ring size so the organic wobble looks proportional
    const shimAmp = shimmerAmount * ring.radius * 0.025;

    ctx.beginPath();
    for (let pi = 0; pi <= RING_POINTS; pi++) {
      const angle = (pi / RING_POINTS) * Math.PI * 2;
      const r2    = ring.radius + shimmerOffset(angle, t, shimAmp);
      const x     = cx + Math.cos(angle) * r2;
      const y     = cy + Math.sin(angle) * r2;
      if (pi === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
    }
    ctx.closePath();
    ctx.stroke();
    ctx.restore();
  }

  // Depth 2+: chord name overlaid at low opacity
  if (theoryDepth >= 2 && currentChord) {
    const cc = COLOR_HEX[currentChord.color] ?? '#ffffff';
    ctx.save();
    ctx.textAlign    = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillStyle    = cc;
    ctx.globalAlpha  = 0.20;
    ctx.font = `bold ${Math.round(w * 0.11)}px system-ui, sans-serif`;
    ctx.fillText(currentChord.name, cx, cy - h * 0.03);
    if (currentChord.nashvilleNumeral) {
      ctx.globalAlpha = 0.12;
      ctx.font = `${Math.round(w * 0.055)}px system-ui, sans-serif`;
      ctx.fillText(currentChord.nashvilleNumeral, cx, cy + h * 0.095);
    }
    ctx.restore();
  }

  // Depth 3: 12-tone chromatic wheel on the outer edge
  if (theoryDepth >= 3) {
    drawChromaticWheel(cx, cy, Math.min(w, h));
  }
}

function drawChromaticWheel(cx: number, cy: number, minDim: number): void {
  const arcR   = minDim * 0.435;
  const thick  = minDim * 0.055;
  const labelR = minDim * 0.475;
  const TAU    = Math.PI * 2;
  const gapRad = 0.03;

  const chordPCs   = new Set<number>(currentChord?.pitchClasses ?? []);
  const scalePCs   = new Set<number>(currentKey?.scaleNotes     ?? []);
  const chordColor = currentChord ? (COLOR_HEX[currentChord.color] ?? '#ffffff') : '#ffffff';

  for (let pc = 0; pc < 12; pc++) {
    const startAngle = (pc / 12) * TAU - Math.PI / 2 + gapRad / 2;
    const endAngle   = ((pc + 1) / 12) * TAU - Math.PI / 2 - gapRad / 2;
    const inChord    = chordPCs.has(pc);
    const inScale    = scalePCs.has(pc);
    const segColor   = inChord ? chordColor : '#ffffff';
    const alpha      = inChord ? 0.90 : inScale ? 0.28 : 0.07;

    ctx.save();
    ctx.globalAlpha = alpha;
    ctx.strokeStyle = segColor;
    ctx.lineWidth   = thick;
    ctx.shadowBlur  = inChord ? 12 : 0;
    ctx.shadowColor = segColor;
    ctx.lineCap     = 'butt';
    ctx.beginPath();
    ctx.arc(cx, cy, arcR, startAngle, endAngle);
    ctx.stroke();
    ctx.restore();

    // Pitch-class label
    const mid = (startAngle + endAngle) / 2;
    const lx  = cx + Math.cos(mid) * labelR;
    const ly  = cy + Math.sin(mid) * labelR;
    ctx.save();
    ctx.globalAlpha    = inChord ? 0.90 : inScale ? 0.35 : 0.10;
    ctx.fillStyle      = '#ffffff';
    ctx.font           = `${Math.round(minDim * 0.026)}px system-ui, sans-serif`;
    ctx.textAlign      = 'center';
    ctx.textBaseline   = 'middle';
    ctx.fillText(NOTE_NAMES_SHARP[pc as PitchClass] ?? '', lx, ly);
    ctx.restore();
  }
}
