import type { Chord } from '../theory/chords.js';
import type { Key } from '../theory/keys.js';
import { ALL_KEYS } from '../theory/keys.js';
import type { PitchClass } from '../theory/notes.js';

export interface KeyCandidate {
  key:   Key;
  score: number;
}

export function inferKey(chordHistory: Chord[]): KeyCandidate[] {
  if (chordHistory.length === 0) return ALL_KEYS.map(key => ({ key, score: 0 }));

  // Collect unique pitch classes from all chord tones in history
  const observedPCs = new Set<PitchClass>();
  for (const chord of chordHistory) {
    for (const pc of chord.pitchClasses) {
      observedPCs.add(pc);
    }
  }

  const totalObserved = observedPCs.size;
  const rootHistory = chordHistory.map(c => c.root);

  const candidates: KeyCandidate[] = ALL_KEYS.map(key => {
    const keyPCSet = new Set<PitchClass>(key.scaleNotes);

    // Coverage: fraction of observed PCs that belong to this key
    let matched = 0;
    for (const pc of observedPCs) {
      if (keyPCSet.has(pc)) matched++;
    }
    const coverage = matched / totalObserved;

    // Tonic boost: any played chord whose root == key tonic
    const tonicBoost = rootHistory.some(r => r === key.tonic) ? 0.15 : 0;

    // Dominant boost: any played chord whose root == scale degree 5
    const dominantRoot = key.scaleNotes[4];
    const dominantBoost = dominantRoot !== undefined && rootHistory.some(r => r === dominantRoot) ? 0.10 : 0;

    // Authentic boost: V→I as the most recent two-chord movement (terminal cadence)
    const authenticBoost = hasRecentAuthenticCadence(rootHistory, key) ? 0.25 : 0;

    const score = coverage + tonicBoost + dominantBoost + authenticBoost;
    return { key, score };
  });

  // Sort descending; tiebreak: major before relative minor
  return candidates.sort((a, b) => {
    const diff = b.score - a.score;
    if (Math.abs(diff) < 0.0001) {
      if (a.key.mode === 'major' && b.key.mode === 'minor') return -1;
      if (a.key.mode === 'minor' && b.key.mode === 'major') return  1;
    }
    return diff;
  });
}

// Check only the most recent two chords for V→I, so a cadence that resolved
// earlier doesn't unfairly boost a key the music has since moved away from.
function hasRecentAuthenticCadence(rootHistory: PitchClass[], key: Key): boolean {
  if (rootHistory.length < 2) return false;
  const dominant = key.scaleNotes[4];
  const tonic    = key.tonic;
  if (dominant === undefined) return false;
  const last  = rootHistory[rootHistory.length - 1];
  const prev  = rootHistory[rootHistory.length - 2];
  return prev === dominant && last === tonic;
}
