import { on } from './render.js';
import { el, qs } from './components.js';
import type { Circuit } from '../session/session.js';
import type { Key } from '../theory/keys.js';

let logList: HTMLElement;
let exportBtn: HTMLButtonElement;
let circuits: Circuit[] = [];
let currentKey: Key | null = null;
let sessionStartedAt = 0;

export function initSessionLog(startedAt: number): void {
  sessionStartedAt = startedAt;

  const sidebar = qs<HTMLElement>('#session-log');
  sidebar.innerHTML = '';

  const header = el('div', { class: 'log-header' }, 'Session Log');
  logList = el('div', { class: 'log-list' });
  logList.append(
    el('div', { class: 'log-empty' },
      'No circuits yet.',
      el('br', {}),
      'Play a resolving progression to capture one.',
    ),
  );

  exportBtn = el('button', { class: 'export-btn' }, 'Export Chart') as HTMLButtonElement;

  sidebar.append(header, logList, exportBtn);

  on('circuit:completed', (event) => {
    circuits = [...circuits, event.circuit];
    appendCircuitEntry(event.circuit);
  });

  on('key:changed', (event) => {
    currentKey = event.key;
  });

  on('session:reset', () => {
    circuits   = [];
    currentKey = null;
    sessionStartedAt = Date.now();
    logList.innerHTML = '';
    logList.append(
      el('div', { class: 'log-empty' },
        'No circuits yet.',
        el('br', {}),
        'Play a resolving progression to capture one.',
      ),
    );
  });

  exportBtn.addEventListener('click', handleExport);
}

function elapsedTime(ts: number): string {
  const secs = Math.floor((ts - sessionStartedAt) / 1000);
  const m = Math.floor(secs / 60);
  const s = secs % 60;
  return `${m}:${s.toString().padStart(2, '0')}`;
}

function appendCircuitEntry(circuit: Circuit): void {
  const empty = logList.querySelector('.log-empty');
  if (empty) empty.remove();

  const resolvedIcon  = circuit.tensionResolved ? '✓' : '↺';
  const resolvedClass = circuit.tensionResolved ? 'resolved' : 'deceptive';
  const cadenceLabel  = circuit.cadences[0]?.pattern.name ?? '';

  const entry = el('div', { class: 'circuit-entry' });
  entry.append(
    el('div', { class: 'circuit-notation' }, circuit.nashvilleNotation),
    el('div', { class: 'circuit-meta' },
      el('span', { class: `circuit-resolved ${resolvedClass}` }, resolvedIcon),
      el('span', { class: 'circuit-cadence' }, cadenceLabel),
      el('span', { class: 'circuit-time' }, elapsedTime(circuit.completedAt)),
    ),
  );

  logList.append(entry);
  entry.scrollIntoView({ behavior: 'smooth', block: 'end' });
}

function handleExport(): void {
  const keyLine = currentKey ? `Key: ${currentKey.name}` : 'Key: Unknown';
  const dateStr = new Date().toISOString().slice(0, 16).replace('T', ' ');
  const lines   = [keyLine, `Session: ${dateStr}`, ''];

  for (const circuit of circuits) {
    const degrees = circuit.nashvilleNotation.split('→');
    lines.push(degrees.join('  |  '));
  }

  const text = lines.join('\n');

  navigator.clipboard.writeText(text).then(() => {
    exportBtn.textContent = 'Copied!';
    setTimeout(() => { exportBtn.textContent = 'Export Chart'; }, 2000);
  }).catch(() => {
    const blob = new Blob([text], { type: 'text/plain' });
    const url  = URL.createObjectURL(blob);
    const a    = document.createElement('a');
    a.href     = url;
    a.download = 'chord-a-long.txt';
    a.click();
    URL.revokeObjectURL(url);
  });
}
