export function el<K extends keyof HTMLElementTagNameMap>(
  tag: K,
  attrs: Record<string, string> = {},
  ...children: (string | Node)[]
): HTMLElementTagNameMap[K] {
  const element = document.createElement(tag);
  for (const [key, val] of Object.entries(attrs)) {
    if (key === 'class') element.className = val;
    else element.setAttribute(key, val);
  }
  for (const child of children) {
    element.append(child);
  }
  return element;
}

export function patchText(element: Element | null, text: string): void {
  if (element && element.textContent !== text) {
    element.textContent = text;
  }
}

export function patchClass(element: Element | null, cls: string, active: boolean): void {
  if (!element) return;
  if (active) element.classList.add(cls);
  else element.classList.remove(cls);
}

export function qs<T extends Element>(selector: string, root: ParentNode = document): T {
  const found = root.querySelector<T>(selector);
  if (!found) throw new Error(`Element not found: ${selector}`);
  return found;
}
