import { emit, on } from './render.js';
import { el, patchText, qs } from './components.js';
import { buildKey } from '../theory/keys.js';
import type { Key } from '../theory/keys.js';
import type { KeyCandidate } from '../engine/key-inference.js';
import { NOTE_NAMES_SHARP, NOTE_NAMES_FLAT } from '../theory/notes.js';
import type { PitchClass } from '../theory/notes.js';

let keyBtn: HTMLButtonElement;
let toastEl: HTMLElement;
let pickerOverlay: HTMLElement;
let pendingCandidates: KeyCandidate[] = [];
let selectedMode: 'major' | 'minor' = 'major';

export function initKeyBar(): void {
  keyBtn    = qs<HTMLButtonElement>('#key-btn');
  toastEl   = qs<HTMLElement>('#key-toast');
  pickerOverlay = qs<HTMLElement>('#key-picker-overlay');

  keyBtn.addEventListener('click', () => openPicker());

  on('key:candidate', (event) => {
    pendingCandidates = event.candidates;
    showToast(event.candidates);
  });

  on('key:changed', (event) => {
    patchText(keyBtn, `Key: ${event.key.name} ▾`);
    hideToast();
    closePicker();
  });

  on('session:reset', () => {
    pendingCandidates = [];
    patchText(keyBtn, 'Key: ? (detecting…)');
    hideToast();
    closePicker();
  });
}

// ── Toast ──────────────────────────────────────────────────────────────────

function isRelativePair(a: KeyCandidate, b: KeyCandidate): boolean {
  if (a.key.mode === b.key.mode) return false;
  const major = a.key.mode === 'major' ? a.key : b.key;
  const minor = a.key.mode === 'minor' ? a.key : b.key;
  return (major.tonic + 9) % 12 === minor.tonic;
}

function showToast(candidates: KeyCandidate[]): void {
  const top    = candidates[0];
  const second = candidates[1];
  if (!top || top.score <= 0.80) { hideToast(); return; }

  const isAmbiguous =
    second !== undefined &&
    Math.abs(top.score - second.score) < 0.05 &&
    isRelativePair(top, second);

  const label = isAmbiguous ? `${top.key.name} / ${second.key.name}` : top.key.name;

  toastEl.innerHTML = '';
  const confirmBtn = el('button', { class: 'toast-confirm' }, 'Confirm');
  const dismissBtn = el('button', { class: 'toast-dismiss' }, '×');

  confirmBtn.addEventListener('click', () => {
    if (top) emit({ type: 'key:changed', key: top.key });
  });
  dismissBtn.addEventListener('click', () => {
    hideToast();
    emit({ type: 'key:dismissed' });
  });

  toastEl.append(
    el('span', { class: 'toast-label' }, `Key detected: ${label}`),
    confirmBtn,
    dismissBtn,
  );
  toastEl.classList.remove('hidden');
}

function hideToast(): void {
  toastEl.classList.add('hidden');
}

// ── Key Picker ─────────────────────────────────────────────────────────────

function openPicker(): void {
  buildPickerContent();
  pickerOverlay.classList.remove('hidden');
}

function closePicker(): void {
  pickerOverlay.classList.add('hidden');
}

function buildPickerContent(): void {
  pickerOverlay.innerHTML = '';

  const panel = el('div', { class: 'picker-panel' });

  // Header
  const closeBtn = el('button', { class: 'picker-close' }, '×');
  closeBtn.addEventListener('click', closePicker);
  panel.append(
    el('div', { class: 'picker-header' },
      el('h3', {}, 'Select Key'),
      closeBtn,
    ),
  );

  // Mode selector
  const majorBtn = el('button', { class: `mode-btn${selectedMode === 'major' ? ' active' : ''}` }, 'Major');
  const minorBtn = el('button', { class: `mode-btn${selectedMode === 'minor' ? ' active' : ''}` }, 'Minor');
  majorBtn.addEventListener('click', () => {
    selectedMode = 'major';
    majorBtn.classList.add('active');
    minorBtn.classList.remove('active');
  });
  minorBtn.addEventListener('click', () => {
    selectedMode = 'minor';
    minorBtn.classList.add('active');
    majorBtn.classList.remove('active');
  });
  panel.append(el('div', { class: 'picker-mode-row' }, majorBtn, minorBtn));

  // 12-note grid
  const noteGrid = el('div', { class: 'picker-note-grid' });
  for (let pc = 0; pc < 12; pc++) {
    const sharp = NOTE_NAMES_SHARP[pc as PitchClass] ?? String(pc);
    const flat  = NOTE_NAMES_FLAT[pc as PitchClass]  ?? String(pc);
    const label = sharp === flat ? sharp : `${sharp}/${flat}`;
    const btn   = el('button', { class: 'note-btn' }, label);
    btn.addEventListener('click', () => {
      emit({ type: 'key:changed', key: buildKey(pc as PitchClass, selectedMode) });
    });
    noteGrid.append(btn);
  }
  panel.append(noteGrid);

  // Detected candidates shortcut
  const validCandidates = pendingCandidates.filter(c => c.score > 0.60);
  if (validCandidates.length > 0) {
    const suggRow = el('div', { class: 'picker-suggestions' });
    suggRow.append(el('p', { class: 'sugg-label' }, 'Detected:'));
    for (const cand of validCandidates.slice(0, 3)) {
      const btn = el('button', { class: 'sugg-btn' },
        `${cand.key.name} (${Math.round(cand.score * 100)}%)`,
      );
      btn.addEventListener('click', () => emit({ type: 'key:changed', key: cand.key }));
      suggRow.append(btn);
    }
    panel.append(suggRow);
  }

  pickerOverlay.append(panel);
  pickerOverlay.addEventListener('click', (e) => {
    if (e.target === pickerOverlay) closePicker();
  }, { once: true });
}

