import type { Chord } from '../theory/chords.js';
import type { Key } from '../theory/keys.js';
import type { CadenceMatch } from '../theory/cadences.js';

export interface SessionEvent {
  id:          string;
  timestamp:   number;
  chord:       Chord;
  source:      'mic' | 'manual';
  confidence?: number;
}

export interface Circuit {
  id:                string;
  startIndex:        number;
  endIndex:          number;
  chords:            Chord[];
  cadences:          CadenceMatch[];
  nashvilleNotation: string;
  tensionResolved:   boolean;
  completedAt:       number;
}

export interface Session {
  id:           string;
  startedAt:    number;
  key:          Key | null;
  keyConfirmed: boolean;
  events:       SessionEvent[];
  circuits:     Circuit[];
}

function randomId(): string {
  return Math.random().toString(36).slice(2, 10);
}

export function createSession(): Session {
  return {
    id:           randomId(),
    startedAt:    Date.now(),
    key:          null,
    keyConfirmed: false,
    events:       [],
    circuits:     [],
  };
}

export function appendChord(
  session: Session,
  chord: Chord,
  source: 'mic' | 'manual',
  confidence?: number,
): Session {
  const lastEvent = session.events[session.events.length - 1];
  if (lastEvent?.chord.name === chord.name) return session;

  const event: SessionEvent = {
    id:        randomId(),
    timestamp: Date.now(),
    chord,
    source,
    ...(confidence !== undefined ? { confidence } : {}),
  };
  return { ...session, events: [...session.events, event] };
}

export function undoLast(session: Session): Session {
  if (session.events.length === 0) return session;
  return { ...session, events: session.events.slice(0, -1) };
}
