import type { PitchClass } from '../theory/notes.js';
import type { Chord } from '../theory/chords.js';
import type { Key } from '../theory/keys.js';
import type { CAGEDShape, ChordVoicing, FretPosition } from './caged.js';

// The 6-quality subset that has CAGED templates.
type TemplateQuality = 'maj' | 'min' | 'dom7' | 'maj7' | 'min7' | 'dim';

interface CAGEDTemplate {
  shape: CAGEDShape;
  quality: TemplateQuality;
  openRootString: 1 | 2 | 3 | 4 | 5 | 6;
  openRootPitchClass: PitchClass;
  // Frets ordered [string6, string5, string4, string3, string2, string1]. -1 = muted.
  frets: [number, number, number, number, number, number];
  fingers: [number, number, number, number, number, number];
}

