// Map chord quality to the nearest template quality (for extended/altered chords).
function toTemplateQuality(quality: string): TemplateQuality {
  switch (quality) {
    case 'maj': case 'sus2': case 'sus4':  return 'maj';
    case 'min':                             return 'min';
    case 'dom7':                            return 'dom7';
    case 'maj7':                            return 'maj7';
    case 'min7': case 'min7b5':            return 'min7';
    case 'dim': case 'dim7':               return 'dim';
    default:                               return 'maj';
  }
}

function transposeShape(template: CAGEDTemplate, targetRoot: PitchClass, chord: Chord): ChordVoicing | null {
  const shift = (targetRoot - template.openRootPitchClass + 12) % 12;
  const baseFret = shift;
  if (baseFret > 12) return null;

  const stringNumbers = [6, 5, 4, 3, 2, 1] as const;
  const positions: FretPosition[] = stringNumbers.map((str, i) => {
    const openFret = template.frets[i] ?? -1;
    return {
      string: str,
      fret: openFret === -1 ? -1 : openFret + shift,
    };
  });

  const label = `${chord.name} (${template.shape}-shape, fret ${baseFret})`;

  if (shift > 0) {
    return {
      chord,
      shape: template.shape,
      baseFret,
      positions,
      barre: { fret: shift, fromString: template.openRootString, toString: 1 as const },
      label,
    };
  }

  return { chord, shape: template.shape, baseFret, positions, label };
}

export function resolveVoicings(chord: Chord, _key?: Key): ChordVoicing[] {
  const tq = toTemplateQuality(chord.quality);
  const voicings: ChordVoicing[] = [];

  for (const template of CAGED_TEMPLATES) {
    if (template.quality !== tq) continue;
    const v = transposeShape(template, chord.root, chord);
    if (v) voicings.push(v);
  }

  // Open-position voicings first; then ascending baseFret; prefer baseFret ≤ 9.
  voicings.sort((a, b) => {
    if (a.baseFret === 0 && b.baseFret !== 0) return -1;
    if (b.baseFret === 0 && a.baseFret !== 0) return  1;
    return a.baseFret - b.baseFret;
  });

  return voicings.slice(0, 3);
}
