import { ChordCasterGame } from '../game/chord-caster.js';
import { buildKey } from '../theory/keys.js';
import type { PitchClass } from '../theory/notes.js';
import { on } from './render.js';
import { qs } from './components.js';

const CANVAS_H = 400;
const CANVAS_PAD = 20;

// Direction control
const SEMITONE_THRESHOLD = 1.5;   // min semitones to count as a new note
const PX_PER_SEMITONE   = 20;     // canvas pixels per semitone of movement
const SILENCE_RESET_FRAMES = 30;  // frames of silence before anchor resets (~500ms)

// Bend detection
const BEND_WINDOW_MS    = 300;
const BEND_MIN_MS       = 180;
const BEND_SEMITONES    = 2.0;
const BEND_MAX_REVERSALS = 1;
const BEND_COOLDOWN_MS  = 1200;
const BEND_STEP_PX      = 70;
const MIN_SHIP_X        = 30;
const MAX_SHIP_X        = 150;

// Trill detection
const TRILL_WINDOW_MS     = 300;
const TRILL_MIN_REVERSALS = 4;
const TRILL_COOLDOWN_MS   = 1200;

const KEY_PC: Record<string, PitchClass> = {
  G: 7, C: 0, D: 2, A: 9, E: 4, F: 5, Bb: 10,
};

interface FreqSample { freq: number; t: number; }

let game: ChordCasterGame | null = null;

// Pitch tracking state (reset on game start)
let lastNoteFreq   = 0;
let silenceFrames  = 0;
let freqWindow: FreqSample[] = [];
let lastBendTime   = 0;
let lastTrillTime  = 0;

function resetPitchState(): void {
  lastNoteFreq  = 0;
  silenceFrames = 0;
  freqWindow    = [];
  lastBendTime  = 0;
  lastTrillTime = 0;
}

function clamp(v: number, lo: number, hi: number): number {
  return Math.max(lo, Math.min(hi, v));
}

export function initGamePanel(): void {
  const gamePanel     = qs<HTMLElement>('#game-panel');
  const canvas        = qs<HTMLCanvasElement>('#game-canvas');
  const startBtn      = qs<HTMLButtonElement>('#game-start-btn');
  const quitBtn       = qs<HTMLButtonElement>('#game-quit-btn');
  const skipTutBtn    = qs<HTMLButtonElement>('#game-tutorial-skip-btn');
  const toggleBtn     = qs<HTMLButtonElement>('#game-toggle-btn');
  const keyBtns       = Array.from(document.querySelectorAll<HTMLButtonElement>('.game-key-btn'));

  game = new ChordCasterGame(canvas);

  game.onTutorialPhaseChange = (phase) => {
    skipTutBtn.classList.toggle('hidden', phase < 0);
  };

  let selectedKeyName: string | null = null;

  toggleBtn.addEventListener('click', () => {
    const isOpen = !gamePanel.classList.contains('hidden');
    if (isOpen) {
      closePanel();
    } else {
      gamePanel.classList.remove('hidden');
      toggleBtn.classList.add('active');
    }
  });

  quitBtn.addEventListener('click', () => closePanel());
  skipTutBtn.addEventListener('click', () => {
    game?.skipTutorial();
    skipTutBtn.classList.add('hidden');
  });

  function closePanel(): void {
    game?.stop();
    gamePanel.classList.add('hidden');
    gamePanel.classList.remove('game-running');
    toggleBtn.classList.remove('active');
    skipTutBtn.classList.add('hidden');
    resetPitchState();
  }

  for (const btn of keyBtns) {
    btn.addEventListener('click', () => {
      keyBtns.forEach(b => b.classList.remove('selected'));
      btn.classList.add('selected');
      selectedKeyName = btn.dataset['key'] ?? null;
      startBtn.classList.add('ready');
    });
  }

  startBtn.addEventListener('click', () => {
    if (!selectedKeyName) return;
    const pc = KEY_PC[selectedKeyName];
    if (pc === undefined) return;
    const key = buildKey(pc, 'major');
    resetPitchState();
    gamePanel.classList.add('game-running');
    game!.start(key);
  });

  canvas.addEventListener('click', (e) => game?.handleClick(e));

  on('pitch:detected', ({ frequency, confidence }) => {
    if (!game || game.status !== 'playing') return;

    const now = performance.now();

    if (confidence < 0.5) {
      silenceFrames++;
      if (silenceFrames >= SILENCE_RESET_FRAMES) lastNoteFreq = 0;
      return;
    }

    silenceFrames = 0;

    // ── Direction control (Y axis) ──────────────────────────────────────────
    if (lastNoteFreq === 0) {
      lastNoteFreq = frequency;
    } else {
      const semitoneDelta = 12 * Math.log2(frequency / lastNoteFreq);
      if (Math.abs(semitoneDelta) >= SEMITONE_THRESHOLD) {
        const yDelta = -Math.sign(semitoneDelta) * Math.abs(semitoneDelta) * PX_PER_SEMITONE;
        game.targetY = clamp(game.targetY + yDelta, CANVAS_PAD, CANVAS_H - CANVAS_PAD);
        lastNoteFreq = frequency;
      }
    }

    // ── Rolling frequency window ────────────────────────────────────────────
    freqWindow.push({ freq: frequency, t: now });
    freqWindow = freqWindow.filter(s => now - s.t < BEND_WINDOW_MS);

    if (freqWindow.length >= 4) {
      const oldest = freqWindow[0]!;
      const newest = freqWindow[freqWindow.length - 1]!;
      const windowMs = newest.t - oldest.t;
      const totalSemitones = 12 * Math.log2(newest.freq / oldest.freq);

      // Count direction reversals
      let reversals = 0;
      for (let i = 1; i < freqWindow.length - 1; i++) {
        const up  = freqWindow[i]!.freq > freqWindow[i - 1]!.freq;
        const up2 = freqWindow[i + 1]!.freq > freqWindow[i]!.freq;
        if (up !== up2) reversals++;
      }

      // ── Bend detection (X axis) ───────────────────────────────────────────
      if (
        windowMs >= BEND_MIN_MS &&
        Math.abs(totalSemitones) >= BEND_SEMITONES &&
        reversals <= BEND_MAX_REVERSALS &&
        now - lastBendTime > BEND_COOLDOWN_MS
      ) {
        if (totalSemitones > 0) {
          game.targetX = Math.min(game.targetX + BEND_STEP_PX, MAX_SHIP_X);
        } else {
          game.targetX = Math.max(game.targetX - BEND_STEP_PX, MIN_SHIP_X);
        }
        lastBendTime = now;
        freqWindow = [];
      }

      // ── Trill detection (evasive dodge) ───────────────────────────────────
      const trillSlice = freqWindow.filter(s => now - s.t < TRILL_WINDOW_MS);
      if (trillSlice.length >= 6 && now - lastTrillTime > TRILL_COOLDOWN_MS) {
        let trillReversals = 0;
        for (let i = 1; i < trillSlice.length - 1; i++) {
          const up  = trillSlice[i]!.freq > trillSlice[i - 1]!.freq;
          const up2 = trillSlice[i + 1]!.freq > trillSlice[i]!.freq;
          if (up !== up2) trillReversals++;
        }
        if (trillReversals >= TRILL_MIN_REVERSALS) {
          game.triggerEvade(now);
          lastTrillTime = now;
        }
      }
    }
  });

  on('chord:confirmed', ({ chord }) => {
    if (!game || game.status !== 'playing' || !game.selectedKey) return;
    const degree = game.selectedKey.scaleNotes.indexOf(chord.root);
    if (degree === -1) return;
    const numeral = game.selectedKey.diatonicChords[degree]?.nashvilleNumeral ?? '';
    game.castSpell(numeral, performance.now());
  });
}

export function stopGamePanel(): void {
  if (!game) return;
  game.stop();
  const gamePanel = document.getElementById('game-panel');
  const toggleBtn = document.getElementById('game-toggle-btn');
  gamePanel?.classList.add('hidden');
  gamePanel?.classList.remove('game-running');
  toggleBtn?.classList.remove('active');
}
