import { createSession, appendChord } from './session/session.js';
import { CircuitTracker } from './session/circuit-tracker.js';
import { inferKey } from './engine/key-inference.js';
import { rankNextChords } from './engine/gps-suggestions.js';
import { resolveVoicings } from './voicings/voicing-lookup.js';
import type { Chord } from './theory/chords.js';
import type { Key } from './theory/keys.js';
import type { ModeName } from './theory/modes.js';
import type { ChordSuggestion } from './engine/gps-suggestions.js';
import type { KeyCandidate } from './engine/key-inference.js';
import type { Session } from './session/session.js';
import { emit, on } from './ui/render.js';
import { initKeyBar } from './ui/key-bar.js';
import { initGpsPanel, updateSuggestions } from './ui/gps-panel.js';
import { initChordPicker } from './ui/chord-picker.js';
import { initSessionLog } from './ui/session-log.js';
import { initModesPanel } from './ui/modes-panel.js';
import { initAudioViz } from './ui/audio-viz.js';
import { initVisualizer } from './ui/visualizer.js';
import { initGamePanel } from './ui/game-panel.js';
import { startListening, stopListening, getAnalyser, getSampleRate, isListening } from './audio/mic-input.js';
import { detectPitches } from './audio/pitch-detector.js';
import { recognizeChord } from './audio/chord-recognizer.js';
import { qs } from './ui/components.js';

interface AppState {
  session:           Session;
  currentChord:      Chord | null;
  suggestions:       ChordSuggestion[];
  keyCandidates:     KeyCandidate[];
  activeMode:        ModeName;
  audioRunning:      boolean;
}

const state: AppState = {
  session:       createSession(),
  currentChord:  null,
  suggestions:   [],
  keyCandidates: [],
  activeMode:    'Ionian',
  audioRunning:  false,
};

const circuitTracker = new CircuitTracker();

// ── Helpers ────────────────────────────────────────────────────────────────

function confirmedKey(): Key | null {
  return state.session.keyConfirmed ? state.session.key : null;
}

function enrichWithKey(chord: Chord, key: Key): Chord {
  const idx = key.scaleNotes.indexOf(chord.root);
  if (idx === -1) return chord;
  const dc = key.diatonicChords[idx];
  // Only substitute when quality matches the diatonic quality
  if (!dc || dc.chord.quality !== chord.quality) return chord;
  return dc.chord;
}

function recomputeSuggestions(): void {
  const key = confirmedKey();
  if (!key || !state.currentChord) { updateSuggestions([]); return; }

  const chords = state.session.events.map(e => e.chord);
  const raw = rankNextChords(state.currentChord, key, chords, state.session.circuits);

  // Populate voicings for each suggestion
  state.suggestions = raw.map(s => ({
    ...s,
    voicings: resolveVoicings(s.chord, key),
  }));

  updateSuggestions(state.suggestions);
}

// ── Event handling ─────────────────────────────────────────────────────────

on('chord:confirmed', (event) => {
  // Keep pending/confirmed tracking in sync for all confirmation sources
  lastPendingName    = event.chord.name;
  lastConfirmedChord = event.chord;
  lastConfirmedTime  = Date.now();

  const key = confirmedKey();
  const chord = key ? enrichWithKey(event.chord, key) : event.chord;

  state.session    = appendChord(state.session, chord, event.source);
  state.currentChord = chord;

  // Circuit detection (requires confirmed key)
  if (key) {
    const circuit = circuitTracker.processNewChord(chord, key);
    if (circuit) {
      state.session = { ...state.session, circuits: [...state.session.circuits, circuit] };
      emit({ type: 'circuit:completed', circuit });
    }
  }

  // Key inference — run after every confirmed chord
  const chordHistory = state.session.events.map(e => e.chord);
  const candidates   = inferKey(chordHistory);
  state.keyCandidates = candidates;

  if (chordHistory.length >= 3 && !state.session.keyConfirmed && !keyToastSuppressed) {
    emit({ type: 'key:candidate', candidates });
  }

  recomputeSuggestions();
});

on('key:changed', (event) => {
  state.session = { ...state.session, key: event.key, keyConfirmed: true };
  keyToastSuppressed = true;
  circuitTracker.reset();
  recomputeSuggestions();
});

on('key:dismissed', () => {
  keyToastSuppressed = true;
});

on('mode:changed', (event) => {
  state.activeMode = event.mode;
});

// ── Audio frame processing ─────────────────────────────────────────────────

interface VoteEntry { name: string; chord: Chord; ts: number }
const voteBuffer: VoteEntry[] = [];
const VOTE_WINDOW_MS = 500;
const VOTES_NEEDED = 3;
const DEBOUNCE_MS = 1500;

let lastConfirmedChord: Chord | null = null;
let lastConfirmedTime = 0;
let lastPendingName: string | null = null;
let confirmationEnabled = true;
let keyToastSuppressed = false;

function onAudioFrame(): void {
  const analyser = getAnalyser();
  if (!analyser) return;

  const pitches = detectPitches(analyser, getSampleRate());

  const best = pitches[0];
  if (best && best.confidence > 0.6) {
    const midi = 12 * Math.log2(best.frequency / 440) + 69;
    const roundedMidi = Math.round(midi);
    const targetHz = 440 * Math.pow(2, (roundedMidi - 69) / 12);
    const cents = Math.round(1200 * Math.log2(best.frequency / targetHz));
    emit({ type: 'pitch:detected', frequency: best.frequency, pitchClass: best.pitchClass, octave: best.octave, cents, confidence: best.confidence });
  }

  const guess = recognizeChord(pitches, confirmedKey());

  if (!guess || guess.confidence < 0.60) {
    if (lastPendingName !== null) {
      lastPendingName = null;
      emit({ type: 'chord:rejected' });
    }
    return;
  }

  const now = Date.now();

  if (guess.confidence < 0.70) {
    if (confirmationEnabled) {
      // Don't re-ask for a chord confirmed within the debounce window
      if (lastConfirmedChord?.name === guess.chord.name && now - lastConfirmedTime < DEBOUNCE_MS) {
        return;
      }
      if (guess.chord.name !== lastPendingName) {
        lastPendingName = guess.chord.name;
        emit({ type: 'chord:pending', guess });
      }
      return;
    }
    // When confirmation is disabled, fall through to vote buffer
  }

  // High confidence — clear any pending overlay
  if (lastPendingName !== null) {
    lastPendingName = null;
    emit({ type: 'chord:rejected' });
  }

  // 3-frame majority vote within 500ms window
  voteBuffer.push({ name: guess.chord.name, chord: guess.chord, ts: now });
  while (voteBuffer.length > 0 && now - (voteBuffer[0]?.ts ?? now) > VOTE_WINDOW_MS) {
    voteBuffer.shift();
  }

  const counts = new Map<string, { count: number; chord: Chord }>();
  for (const v of voteBuffer) {
    const entry = counts.get(v.name);
    if (entry) { entry.count++; } else { counts.set(v.name, { count: 1, chord: v.chord }); }
  }

  for (const [name, { count, chord }] of counts) {
    if (count >= VOTES_NEEDED) {
      if (lastConfirmedChord?.name === name && now - lastConfirmedTime < DEBOUNCE_MS) break;
      lastConfirmedChord = chord;
      lastConfirmedTime = now;
      voteBuffer.length = 0;
      emit({ type: 'chord:confirmed', chord, source: 'mic' });
      break;
    }
  }
}

// ── Boot ───────────────────────────────────────────────────────────────────

function initClearButton(): void {
  const btn = qs<HTMLButtonElement>('#clear-btn');
  btn.addEventListener('click', () => {
    state.session       = createSession();
    state.currentChord  = null;
    state.suggestions   = [];
    state.keyCandidates = [];
    circuitTracker.reset();
    lastConfirmedChord = null;
    lastConfirmedTime  = 0;
    lastPendingName    = null;
    keyToastSuppressed = false;
    voteBuffer.length  = 0;
    emit({ type: 'session:reset' });
  });
}

function init(): void {
  initKeyBar();
  initGpsPanel();
  initChordPicker();
  initSessionLog(state.session.startedAt);
  initModesPanel();
  initListenButton();
  initConfirmToggle();
  initClearButton();
  initAudioViz();
  initVisualizer();
  initGamePanel();
  console.log('Chord-A-Long loaded');
}

async function populateDevicePicker(sel: HTMLSelectElement): Promise<void> {
  const devices = await navigator.mediaDevices.enumerateDevices();
  const inputs = devices.filter(d => d.kind === 'audioinput');
  const current = sel.value;
  sel.innerHTML = '<option value="">Default mic</option>';
  inputs.forEach((d, i) => {
    const opt = document.createElement('option');
    opt.value = d.deviceId;
    opt.textContent = d.label || `Input ${i + 1}`;
    if (d.deviceId === current) opt.selected = true;
    sel.appendChild(opt);
  });
}

const CONFIRM_STORAGE_KEY = 'chord-a-long:confirm';

function initConfirmToggle(): void {
  const btn = qs<HTMLButtonElement>('#confirm-toggle');

  // Restore saved preference before mic starts
  if (localStorage.getItem(CONFIRM_STORAGE_KEY) === '0') {
    confirmationEnabled = false;
    btn.textContent = 'Confirm: Off';
    btn.classList.remove('on');
  }

  btn.addEventListener('click', () => {
    confirmationEnabled = !confirmationEnabled;
    localStorage.setItem(CONFIRM_STORAGE_KEY, confirmationEnabled ? '1' : '0');
    btn.textContent = confirmationEnabled ? 'Confirm: On' : 'Confirm: Off';
    btn.classList.toggle('on', confirmationEnabled);
    if (!confirmationEnabled && lastPendingName !== null) {
      lastPendingName = null;
      emit({ type: 'chord:rejected' });
    }
  });
}

function initListenButton(): void {
  const listenBtn    = qs<HTMLButtonElement>('#listen-btn');
  const deniedBanner = qs<HTMLElement>('#mic-denied-banner');
  const deviceSel    = qs<HTMLSelectElement>('#audio-device-select');

  void populateDevicePicker(deviceSel);

  listenBtn.addEventListener('click', () => {
    void (async () => {
      if (isListening()) {
        stopListening();
        state.audioRunning = false;
        listenBtn.textContent = '● Mic Off';
        listenBtn.classList.remove('active');
        emit({ type: 'audio:stopped' });
        return;
      }
      // Hide any previous denied banner
      deniedBanner.classList.remove('visible');
      try {
        listenBtn.textContent = '⋯ Connecting…';
        listenBtn.disabled = true;
        // Save label before re-enumeration — deviceId may be empty if permission
        // hadn't been granted yet when the picker was first populated.
        const selectedLabel = deviceSel.options[deviceSel.selectedIndex]?.text ?? '';
        let deviceId = deviceSel.value || undefined;
        await startListening(onAudioFrame, deviceId);
        // Re-enumerate now that permission is granted to get real device IDs.
        await populateDevicePicker(deviceSel);
        // If we started without a real deviceId, find the device by label and restart.
        if (!deviceId && selectedLabel && selectedLabel !== 'Default mic') {
          const match = Array.from(deviceSel.options).find(o => o.text === selectedLabel && o.value);
          if (match) {
            stopListening();
            deviceId = match.value;
            await startListening(onAudioFrame, deviceId);
          }
        }
        if (deviceId) deviceSel.value = deviceId;
        state.audioRunning = true;
        listenBtn.textContent = '● Listening';
        listenBtn.classList.add('active');
        listenBtn.disabled = false;
        emit({ type: 'audio:started' });
      } catch {
        listenBtn.textContent = '⚠ Mic denied';
        listenBtn.disabled = false;
        deniedBanner.classList.add('visible');
        // Auto-hide after 8 seconds
        setTimeout(() => deniedBanner.classList.remove('visible'), 8000);
      }
    })();
  });
}

init();
