import type { PitchClass } from './notes.js';
import { noteName } from './notes.js';
import { buildChord } from './chords.js';
import type { ChordColor, ChordQuality, Chord } from './chords.js';

export interface DiatonicChord {
  degree:           1|2|3|4|5|6|7;
  chord:            Chord;
  nashvilleNumeral: string;
  tensionScore:     number;
}

export interface Key {
  tonic:          PitchClass;
  mode:           'major' | 'minor';
  name:           string;
  preferFlats:    boolean;
  scaleNotes:     PitchClass[];
  diatonicChords: DiatonicChord[];
}

// W W H W W W H
const MAJOR_INTERVALS = [2, 2, 1, 2, 2, 2, 1];
// W H W W H W W
const MINOR_INTERVALS = [2, 1, 2, 2, 1, 2, 2];

// Diatonic chord qualities for major scale degrees 1–7
const MAJOR_QUALITIES: ChordQuality[] = ['maj','min','min','maj','dom7','min','dim'];
// Diatonic chord qualities for natural minor scale degrees 1–7
const MINOR_QUALITIES: ChordQuality[] = ['min','dim','maj','min','min','maj','maj'];

// Nashville numerals
const MAJOR_NUMERALS = ['1','2m','3m','4','5','6m','7°'];
const MINOR_NUMERALS = ['1m','2°','3','4m','5m','6','7'];

// Harmonic function colors for major
const MAJOR_COLORS: ChordColor[] = ['warm-gold','cool-blue','green','warm-gold','orange','green','purple'];
// Harmonic function colors for minor
const MINOR_COLORS: ChordColor[] = ['green','purple','warm-gold','cool-blue','cool-blue','warm-gold','orange'];

// Tension scores per degree (1-indexed → index 0 = degree 1)
const TENSION_SCORES = [0.00, 0.55, 0.25, 0.45, 0.85, 0.15, 1.00];

// Keys that prefer flat notation
const FLAT_KEYS = new Set<number>([5, 10, 3, 8, 1, 6]); // F, Bb, Eb, Ab, Db, Gb (pitch classes)

export function buildKey(tonic: PitchClass, mode: 'major' | 'minor'): Key {
  const intervals = mode === 'major' ? MAJOR_INTERVALS : MINOR_INTERVALS;
  const qualities = mode === 'major' ? MAJOR_QUALITIES : MINOR_QUALITIES;
  const numerals  = mode === 'major' ? MAJOR_NUMERALS  : MINOR_NUMERALS;
  const colors    = mode === 'major' ? MAJOR_COLORS    : MINOR_COLORS;
  const preferFlats = FLAT_KEYS.has(tonic);

  // Build scale notes
  const scaleNotes: PitchClass[] = [tonic];
  let current = tonic;
  for (let i = 0; i < 6; i++) {
    current = ((current + (intervals[i] ?? 0)) % 12) as PitchClass;
    scaleNotes.push(current);
  }

  // Build diatonic chords
  const diatonicChords: DiatonicChord[] = scaleNotes.map((root, i) => {
    const degree = (i + 1) as 1|2|3|4|5|6|7;
    const quality = qualities[i] ?? 'maj';
    const numeral = numerals[i] ?? String(degree);
    const color = colors[i] ?? 'neutral';
    const tension = TENSION_SCORES[i] ?? 0;
    const chord = buildChord(root, quality, preferFlats, numeral, degree, color);
    return { degree, chord, nashvilleNumeral: numeral, tensionScore: tension };
  });

  const tonicName = noteName(tonic, preferFlats);
  const modeName = mode === 'major' ? 'Major' : 'Minor';
  const name = `${tonicName} ${modeName}`;

  return { tonic, mode, name, preferFlats, scaleNotes, diatonicChords };
}

// Pre-build all 24 keys
export const ALL_KEYS: Key[] = (() => {
  const keys: Key[] = [];
  for (let pc = 0; pc < 12; pc++) {
    keys.push(buildKey(pc as PitchClass, 'major'));
    keys.push(buildKey(pc as PitchClass, 'minor'));
  }
  return keys;
})();

export function getScaleDegree(pitchClass: PitchClass, key: Key): number {
  return key.scaleNotes.indexOf(pitchClass) + 1; // 0 if not in key
}

export function getDiatonicChord(degree: 1|2|3|4|5|6|7, key: Key): DiatonicChord {
  const dc = key.diatonicChords[degree - 1];
  if (!dc) throw new Error(`Invalid degree ${degree}`);
  return dc;
}
