import type { Chord } from '../theory/chords.js';
import type { Key } from '../theory/keys.js';
import type { ChordVoicing } from '../voicings/caged.js';
import type { Circuit } from '../session/session.js';
import { CADENCE_PATTERNS } from '../theory/cadences.js';

export type { Circuit };

export interface ChordSuggestion {
  chord:            Chord;
  tensionScore:     number;
  reasons:          string[];
  nashvilleNumeral: string;
  voicings:         ChordVoicing[]; // populated in Phase 3
}

export function rankNextChords(
  current: Chord,
  key:     Key,
  history: Chord[],
  circuits: Circuit[],
): ChordSuggestion[] {
  // Start with all 7 diatonic chords
  const candidates = key.diatonicChords.map(dc => ({
    dc,
    score:   dc.tensionScore,
    reasons: [] as string[],
  }));

  // Determine current chord's degree in this key
  const currentDegreeIdx = key.scaleNotes.indexOf(current.root);
  const currentDegree = currentDegreeIdx === -1 ? 0 : currentDegreeIdx + 1;

  // 1. Apply cadence-pattern hints
  if (currentDegree > 0) {
    for (const candidate of candidates) {
      const candDegree = candidate.dc.degree;
      for (const pattern of CADENCE_PATTERNS) {
        const precursor = pattern.degrees.indexOf(candDegree);
        if (precursor <= 0) continue; // candidate must be after current in pattern
        if (pattern.degrees[precursor - 1] !== currentDegree) continue;
        // current → candidate matches a cadence pattern
        if (pattern.tensionResolved) {
          candidate.score -= 0.30;
          candidate.reasons.push(`Resolves via ${pattern.name}`);
        } else {
          candidate.score -= 0.15;
          candidate.reasons.push(`Builds via ${pattern.name}`);
        }
      }
    }
  }

  // 2. Session history frequency boost (+0.05 per prior play, max +0.20)
  if (history.length > 0) {
    for (const candidate of candidates) {
      const plays = history.filter(c => c.root === candidate.dc.chord.root).length;
      const boost = Math.min(plays * 0.05, 0.20);
      if (boost > 0) {
        candidate.score += boost;
        candidate.reasons.push(`Played ${plays}x before`);
      }
    }
  }

  // 3. Circuit continuation boost
  if (circuits.length > 0 && history.length > 0) {
    for (const candidate of candidates) {
      for (const circuit of circuits) {
        const circuitDegrees = circuit.chords.map(c => {
          const idx = key.scaleNotes.indexOf(c.root);
          return idx === -1 ? 0 : idx + 1;
        });
        // Check if the last N chords in history match the beginning of this circuit
        for (let len = 1; len < circuitDegrees.length; len++) {
          const histSlice = history.slice(-len).map(c => {
            const idx = key.scaleNotes.indexOf(c.root);
            return idx === -1 ? 0 : idx + 1;
          });
          if (histSlice.every((d, i) => d === circuitDegrees[i])) {
            const nextCircuitDegree = circuitDegrees[len];
            if (nextCircuitDegree !== undefined && nextCircuitDegree === candidate.dc.degree) {
              candidate.score -= 0.20;
              candidate.reasons.push('Circuit continuation');
            }
          }
        }
      }
    }
  }

  // Sort ascending by score
  candidates.sort((a, b) => a.score - b.score);

  return candidates.map(c => ({
    chord:            c.dc.chord,
    tensionScore:     c.score,
    reasons:          c.reasons,
    nashvilleNumeral: c.dc.nashvilleNumeral,
    voicings:         [],
  }));
}
