import type { ChordVoicing } from '../voicings/caged.js';

const W = 150;
const H = 145;
// String x positions for strings 6..1 (low E → high e, left → right)
const SX: [number, number, number, number, number, number] = [12, 28, 44, 60, 76, 92];
const MARKER_Y = 12;
const NUT_Y = 26;
const FRET_H = 22;
const NUM_FRETS = 4;
const R = 8;

function stringX(stringNum: 1 | 2 | 3 | 4 | 5 | 6): number {
  // string 6 → index 0 → SX[0]; string 1 → index 5 → SX[5]
  return SX[6 - stringNum] ?? SX[0] ?? 12;
}

export function buildDiagramSVG(voicing: ChordVoicing): string {
  const isOpen = voicing.baseFret === 0;
  const parts: string[] = [];

  parts.push(`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${W} ${H}" width="${W}" height="${H}" class="chord-diagram">`);

  // Fret position label for barre chords — placed right of the last string to avoid clipping
  if (!isOpen) {
    const labelX = (SX[5] ?? 92) + 12;
    parts.push(
      `<text x="${labelX}" y="${NUT_Y - 6}" font-size="15" fill="var(--text)"` +
      ` text-anchor="start" font-family="monospace" font-weight="600">${voicing.baseFret}fr</text>`,
    );
  }

  // String lines (vertical)
  for (const x of SX) {
    parts.push(
      `<line x1="${x}" y1="${NUT_Y}" x2="${x}" y2="${NUT_Y + NUM_FRETS * FRET_H}"` +
      ` stroke="var(--border)" stroke-width="1.5"/>`,
    );
  }

  // Fret/nut lines (horizontal)
  for (let f = 0; f <= NUM_FRETS; f++) {
    const y = NUT_Y + f * FRET_H;
    const x1 = SX[0] ?? 12;
    const x2 = SX[5] ?? 92;
    if (f === 0 && isOpen) {
      // Thick nut
      parts.push(`<rect x="${x1}" y="${y - 3}" width="${x2 - x1}" height="5" rx="1" fill="var(--text)"/>`);
    } else {
      parts.push(`<line x1="${x1}" y1="${y}" x2="${x2}" y2="${y}" stroke="var(--border)" stroke-width="1"/>`);
    }
  }

  // Barre bar
  if (voicing.barre) {
    const { fret, fromString, toString: toStr } = voicing.barre;
    const row = fret - voicing.baseFret;
    const cy = NUT_Y + row * FRET_H + FRET_H / 2;
    const x1 = stringX(fromString as 1 | 2 | 3 | 4 | 5 | 6);
    const x2 = stringX(toStr as 1 | 2 | 3 | 4 | 5 | 6);
    parts.push(
      `<rect x="${x1 - R}" y="${cy - R}" width="${x2 - x1 + R * 2}"` +
      ` height="${R * 2}" rx="${R}" fill="var(--text)"/>`,
    );
  }

  // Markers and note dots
  for (const pos of voicing.positions) {
    const x = stringX(pos.string);

    if (pos.fret === -1) {
      parts.push(
        `<text x="${x}" y="${MARKER_Y + 4}" font-size="12" fill="var(--text-dim)"` +
        ` text-anchor="middle">×</text>`,
      );
    } else if (pos.fret === 0 && isOpen) {
      parts.push(
        `<circle cx="${x}" cy="${MARKER_Y}" r="5" fill="none"` +
        ` stroke="var(--text)" stroke-width="1.5"/>`,
      );
    } else {
      const row = isOpen ? pos.fret - 1 : pos.fret - voicing.baseFret;
      if (row >= 0 && row < NUM_FRETS) {
        // Skip individual dot if it's covered by the barre
        const onBarre = voicing.barre !== undefined && pos.fret === voicing.barre.fret;
        if (!onBarre) {
          const cy = NUT_Y + row * FRET_H + FRET_H / 2;
          parts.push(`<circle cx="${x}" cy="${cy}" r="${R}" fill="var(--text)"/>`);
        }
      }
    }
  }

  parts.push('</svg>');
  return parts.join('');
}
