import { emit } from './render.js';
import { el, qs } from './components.js';
import { buildChord } from '../theory/chords.js';
import type { ChordQuality } from '../theory/chords.js';
import type { PitchClass } from '../theory/notes.js';
import { NOTE_NAMES_SHARP, NOTE_NAMES_FLAT } from '../theory/notes.js';

const QUALITIES: { quality: ChordQuality; label: string }[] = [
  { quality: 'maj',   label: 'Major' },
  { quality: 'min',   label: 'Minor' },
  { quality: 'dom7',  label: 'Dom 7' },
  { quality: 'maj7',  label: 'Maj 7' },
  { quality: 'min7',  label: 'Min 7' },
  { quality: 'dim',   label: 'Dim' },
];

let overlay: HTMLElement;
let selectedPc: PitchClass | null = null;
let selectedQuality: ChordQuality = 'maj';

export function initChordPicker(): void {
  overlay = qs<HTMLElement>('#chord-picker-overlay');
  qs<HTMLButtonElement>('#manual-btn').addEventListener('click', openPicker);
  buildPickerContent();
}

function openPicker(): void {
  selectedPc = null;
  selectedQuality = 'maj';
  buildPickerContent();
  overlay.classList.remove('hidden');
}

function closePicker(): void {
  overlay.classList.add('hidden');
}

function buildPickerContent(): void {
  overlay.innerHTML = '';
  const panel = el('div', { class: 'picker-panel' });

  // Header
  const closeBtn = el('button', { class: 'picker-close' }, '×');
  closeBtn.addEventListener('click', closePicker);
  panel.append(
    el('div', { class: 'picker-header' },
      el('h3', {}, 'Select Chord'),
      closeBtn,
    ),
  );

  // Root note grid (12 notes)
  const noteGrid = el('div', { class: 'picker-note-grid' });
  for (let pc = 0; pc < 12; pc++) {
    const sharp = NOTE_NAMES_SHARP[pc as PitchClass] ?? String(pc);
    const flat  = NOTE_NAMES_FLAT[pc as PitchClass]  ?? String(pc);
    const label = sharp === flat ? sharp : `${sharp}/${flat}`;
    const btn   = el('button', { class: 'note-btn', 'data-pc': String(pc) }, label);
    btn.addEventListener('click', () => {
      selectedPc = pc as PitchClass;
      noteGrid.querySelectorAll('.note-btn').forEach(b => b.classList.remove('active'));
      btn.classList.add('active');
    });
    noteGrid.append(btn);
  }
  panel.append(el('p', { class: 'picker-section-label' }, 'Root'), noteGrid);

  // Quality grid
  const qualityGrid = el('div', { class: 'picker-quality-grid' });
  for (const { quality, label } of QUALITIES) {
    const btn = el('button', {
      class: `quality-btn${quality === selectedQuality ? ' active' : ''}`,
      'data-quality': quality,
    }, label);
    btn.addEventListener('click', () => {
      selectedQuality = quality;
      qualityGrid.querySelectorAll('.quality-btn').forEach(b => b.classList.remove('active'));
      btn.classList.add('active');
    });
    qualityGrid.append(btn);
  }
  panel.append(el('p', { class: 'picker-section-label' }, 'Quality'), qualityGrid);

  // Confirm button
  const confirmBtn = el('button', { class: 'picker-confirm-btn' }, 'Add Chord');
  confirmBtn.addEventListener('click', () => {
    if (selectedPc === null) return;
    const chord = buildChord(selectedPc, selectedQuality);
    emit({ type: 'chord:confirmed', chord, source: 'manual' });
    closePicker();
  });
  panel.append(confirmBtn);

  overlay.append(panel);
  overlay.addEventListener('click', (e) => {
    if (e.target === overlay) closePicker();
  }, { once: true });
}
