import type { Chord } from '../theory/chords.js';
import type { Key } from '../theory/keys.js';
import { CADENCE_PATTERNS, type CadenceMatch } from '../theory/cadences.js';

export type { CadenceMatch };

export function scanCadences(history: Chord[], key: Key): CadenceMatch[] {
  if (history.length < 2) return [];

  // Map each chord to its diatonic scale degree (1–7), or 0 if chromatic
  const degrees = history.map(chord => {
    const idx = key.scaleNotes.indexOf(chord.root);
    return idx === -1 ? 0 : idx + 1;
  });

  const matches: CadenceMatch[] = [];

  // Check windows of length 3 first, then 2
  for (let len = 3; len >= 2; len--) {
    for (let i = 0; i <= degrees.length - len; i++) {
      const window = degrees.slice(i, i + len);
      if (window.some(d => d === 0)) continue; // chromatic chord in window — skip

      for (const pattern of CADENCE_PATTERNS) {
        if (pattern.degrees.length !== len) continue;
        if (pattern.degrees.every((d, j) => d === window[j])) {
          // Check deduplication: if this is a 2-chord match, skip if it's the tail of a 3-chord match already captured
          if (len === 2) {
            const alreadyCovered = matches.some(
              m => m.pattern.degrees.length === 3 && m.endIndex === i + len - 1 &&
                   m.degrees.slice(-2).every((d, j) => d === window[j])
            );
            if (alreadyCovered) continue;
          }
          matches.push({
            pattern,
            startIndex: i,
            endIndex:   i + len - 1,
            degrees:    window,
          });
        }
      }
    }
  }

  return matches;
}
