import type { Key } from '../theory/keys.js';
import { WAVES } from './wave-data.js';

// ── Types ─────────────────────────────────────────────────────────────────

interface Enemy {
  x: number;
  y: number;
  dead: boolean;
}

interface Projectile {
  x: number;
  y: number;
  dead: boolean;
}

interface Particle {
  x: number;
  y: number;
  vx: number;
  vy: number;
  life: number;  // 0–1, decrements to 0
  color: string;
}

interface Star {
  x: number;
  y: number;
}

// ── Constants ─────────────────────────────────────────────────────────────

const W = 800;
const H = 400;

const SHIP_X     = 60;
const MIN_SHIP_X = 30;
const MAX_SHIP_X = 150;

const EVADE_COOLDOWN_MS = 1500;
const EVADE_DODGE_PX    = 130;
const EVADE_DUR         = 0.5;   // sec

const ENEMY_W = 20;
const ENEMY_H = 14;
const ENEMY_COL_SPACING = 48;
const ENEMY_ROW_SPACING = 32;
const ENEMY_START_Y = 44;

const PROJ_W = 18;
const PROJ_H = 6;
const PROJ_SPEED = 500;          // px/sec rightward

const FREQ_MIN = 82;             // low E open
const FREQ_MAX = 1319;           // high E 22nd fret

const SHIELD_FLASH_DUR = 0.35;  // sec
const WAVE_LABEL_DUR = 3.0;     // sec
const PARTICLE_DUR = 0.6;       // sec
const NUM_STARS = 80;

// ── Exported utilities ────────────────────────────────────────────────────

/** Map guitar frequency to canvas Y. High freq → top of canvas. */
export function freqToY(freq: number): number {
  const t = Math.max(0, Math.min(1, (freq - FREQ_MIN) / (FREQ_MAX - FREQ_MIN)));
  return H - t * (H - 40) - 20;
}

// ── Game class ────────────────────────────────────────────────────────────

export class ChordCasterGame {
  private readonly canvas: HTMLCanvasElement;
  private readonly ctx: CanvasRenderingContext2D;
  private rafId: number | null = null;
  private lastTime = 0;

  status: 'idle' | 'countdown' | 'tutorial' | 'playing' | 'gameover' = 'idle';
  selectedKey: Key | null = null;
  targetY = H / 2;
  targetX = SHIP_X;

  private shipY = H / 2;
  private shipX = SHIP_X;
  private hull = 3;
  private score = 0;
  private waveIndex = 0;
  private waveLabel = '';
  private waveLabelTimer = 0;
  private enemies: Enemy[] = [];
  private projectiles: Projectile[] = [];
  private particles: Particle[] = [];
  private shieldActive = false;
  private shieldFlashTimer = 0;
  private healFlashTimer = 0;
  private evadeTimer = 0;
  private lastEvadeTime = 0;
  private spellCooldowns = { fire: 0, shield: 0, heal: 0, rapidFire: 0 };
  private rapidFireQueue = 0;
  private rapidFireTimer = 0;
  private readonly stars: Star[] = [];
  private countdownValue = 3;
  private countdownTimer = 1;
  private enemySpeed = 30;

  // Tutorial state
  private tutPhase: 0 | 1 | 2 = 0;  // 0=steer, 1=fire, 2=done
  private tutTimer = 0;
  private tutTargetY = H / 2;
  private tutFired = false;
  onTutorialPhaseChange?: (phase: number) => void;

  private colorDominant = '#d4621a';
  private colorTonic = '#c9a227';

  onGameOver?: (score: number) => void;

  constructor(canvas: HTMLCanvasElement) {
    this.canvas = canvas;
    const ctx = canvas.getContext('2d');
    if (!ctx) throw new Error('Canvas 2d context unavailable');
    this.ctx = ctx;
    this.generateStars();
  }

  // ── Public API ───────────────────────────────────────────────────────────

  start(key: Key): void {
    this.selectedKey = key;
    this.hull = 3;
    this.score = 0;
    this.waveIndex = 0;
    this.enemies = [];
    this.projectiles = [];
    this.particles = [];
    this.shieldActive = false;
    this.shieldFlashTimer = 0;
    this.healFlashTimer = 0;
    this.spellCooldowns = { fire: 0, shield: 0, heal: 0, rapidFire: 0 };
    this.rapidFireQueue = 0;
    this.rapidFireTimer = 0;
    this.shipY = H / 2;
    this.shipX = SHIP_X;
    this.targetY = H / 2;
    this.targetX = SHIP_X;
    this.evadeTimer = 0;
    this.lastEvadeTime = 0;
    this.countdownValue = 3;
    this.countdownTimer = 1;
    this.status = 'countdown';
    this.readColors();
    this.startLoop();
  }

  stop(): void {
    if (this.rafId !== null) {
      cancelAnimationFrame(this.rafId);
      this.rafId = null;
    }
    this.status = 'idle';
  }

  skipTutorial(): void {
    if (this.status !== 'tutorial') return;
    this.enemies = [];
    this.projectiles = [];
    this.status = 'playing';
    this.spawnWave(0);
    this.onTutorialPhaseChange?.(-1);
  }

  castSpell(numeral: string, now: number): void {
    if (this.status !== 'playing' && this.status !== 'tutorial') return;
    if (numeral === '5' && now > this.spellCooldowns.fire) {
      if (this.status === 'playing') this.snapToNearestEnemyRow();
      this.spawnProjectile();
      this.tutFired = true;
      this.spellCooldowns.fire = now + 400;
    } else if (numeral === '7°' && now > this.spellCooldowns.rapidFire) {
      this.snapToNearestEnemyRow();
      this.rapidFireQueue = 10;
      this.rapidFireTimer = 0;
      this.spellCooldowns.rapidFire = now + 4000;
    } else if (numeral === '1' && now > this.spellCooldowns.shield) {
      this.shieldActive = true;
      this.spellCooldowns.shield = now + 800;
    } else if (numeral === '4' && now > this.spellCooldowns.heal && this.hull < 3) {
      this.hull++;
      this.healFlashTimer = 0.5;
      this.spellCooldowns.heal = now + 4000;
    }
  }

  triggerEvade(now: number): void {
    if (this.status !== 'playing' && this.status !== 'tutorial') return;
    if (now - this.lastEvadeTime < EVADE_COOLDOWN_MS) return;
    this.lastEvadeTime = now;
    this.evadeTimer = EVADE_DUR;

    const nearby = this.enemies.filter(e => e.x > this.shipX && e.x < this.shipX + 250);
    const above  = nearby.filter(e => e.y < this.shipY).length;
    const below  = nearby.filter(e => e.y > this.shipY).length;

    const dodgeUp = below >= above;
    this.targetY = dodgeUp
      ? Math.max(20, this.shipY - EVADE_DODGE_PX)
      : Math.min(H - 20, this.shipY + EVADE_DODGE_PX);
  }

  handleClick(e: MouseEvent): void {
    if (this.status !== 'gameover') return;
    const rect = this.canvas.getBoundingClientRect();
    const x = (e.clientX - rect.left) * (W / rect.width);
    const y = (e.clientY - rect.top) * (H / rect.height);
    // "PLAY AGAIN" button: centered at y=270, 220×40
    if (x >= 290 && x <= 510 && y >= 250 && y <= 290) {
      if (this.selectedKey) this.start(this.selectedKey);
    }
  }

  // ── Private: init ─────────────────────────────────────────────────────────

  private generateStars(): void {
    for (let i = 0; i < NUM_STARS; i++) {
      this.stars.push({ x: Math.random() * W, y: Math.random() * H });
    }
  }

  private readColors(): void {
    const cs = getComputedStyle(document.documentElement);
    const dom = cs.getPropertyValue('--color-dominant').trim();
    const ton = cs.getPropertyValue('--color-tonic').trim();
    if (dom) this.colorDominant = dom;
    if (ton) this.colorTonic = ton;
  }

  private startLoop(): void {
    if (this.rafId !== null) return;
    const tick = (timestamp: number): void => {
      const dt = this.lastTime > 0 ? Math.min((timestamp - this.lastTime) / 1000, 0.1) : 0;
      this.lastTime = timestamp;
      this.update(dt);
      this.render();
      if (this.status !== 'idle') {
        this.rafId = requestAnimationFrame(tick);
      } else {
        this.rafId = null;
      }
    };
    this.lastTime = 0;
    this.rafId = requestAnimationFrame(tick);
  }

  // ── Private: update ───────────────────────────────────────────────────────

  private update(dt: number): void {
    if (this.status === 'countdown') {
      this.countdownTimer -= dt;
      if (this.countdownTimer <= 0) {
        this.countdownValue--;
        if (this.countdownValue < 0) {
          this.startTutorial();
        } else {
          // Show "GO!" briefly after reaching 0
          this.countdownTimer = this.countdownValue === 0 ? 0.6 : 1.0;
        }
      }
      return;
    }

    const inPlay = this.status === 'playing' || this.status === 'tutorial';
    if (!inPlay) return;

    // Frame-rate independent lerp (0.12 factor at 60 fps)
    this.shipY += (this.targetY - this.shipY) * (1 - Math.pow(0.88, dt * 60));
    this.shipX += (this.targetX - this.shipX) * (1 - Math.pow(0.88, dt * 60));

    if (this.evadeTimer > 0) this.evadeTimer -= dt;

    if (this.rapidFireQueue > 0) {
      this.rapidFireTimer -= dt;
      if (this.rapidFireTimer <= 0) {
        this.spawnProjectile();
        this.rapidFireQueue--;
        this.rapidFireTimer = 0.08;
      }
    }

    for (const p of this.projectiles) p.x += PROJ_SPEED * dt;
    for (const e of this.enemies)     e.x -= this.enemySpeed * dt;

    // Projectile ↔ enemy collisions
    for (const proj of this.projectiles) {
      if (proj.dead) continue;
      for (const enemy of this.enemies) {
        if (enemy.dead) continue;
        if (
          proj.x < enemy.x + ENEMY_W && proj.x + PROJ_W > enemy.x &&
          proj.y < enemy.y + ENEMY_H && proj.y + PROJ_H > enemy.y
        ) {
          proj.dead = true;
          enemy.dead = true;
          if (this.status === 'playing') this.score += 10;
          this.spawnParticles(enemy.x + ENEMY_W / 2, enemy.y + ENEMY_H / 2);
        }
      }
    }

    // Enemies reaching left edge
    for (const enemy of this.enemies) {
      if (enemy.dead || enemy.x + ENEMY_W > 0) continue;
      enemy.dead = true;
      if (this.status === 'tutorial') continue; // no damage in tutorial
      if (this.shieldActive) {
        this.shieldActive = false;
        this.shieldFlashTimer = SHIELD_FLASH_DUR;
      } else {
        this.hull--;
        if (this.hull <= 0) {
          this.hull = 0;
          this.status = 'gameover';
          this.onGameOver?.(this.score);
          return;
        }
      }
    }

    this.projectiles = this.projectiles.filter(p => !p.dead && p.x < W + PROJ_W);
    this.enemies     = this.enemies.filter(e => !e.dead);

    for (const p of this.particles) {
      p.x += p.vx * dt;
      p.y += p.vy * dt;
      p.life -= dt / PARTICLE_DUR;
    }
    this.particles = this.particles.filter(p => p.life > 0);

    if (this.waveLabelTimer  > 0) this.waveLabelTimer  -= dt;
    if (this.shieldFlashTimer > 0) this.shieldFlashTimer -= dt;
    if (this.healFlashTimer   > 0) this.healFlashTimer   -= dt;

    if (this.status === 'tutorial') {
      this.updateTutorial(dt);
    } else if (this.enemies.length === 0) {
      this.waveIndex++;
      this.spawnWave(this.waveIndex);
    }
  }

  private updateTutorial(dt: number): void {
    this.tutTimer += dt;

    if (this.tutPhase === 0) {
      // Advance when ship reaches target Y or after timeout
      if (Math.abs(this.shipY - this.tutTargetY) < 35 || this.tutTimer > 8) {
        this.advanceTutorialPhase();
      }
    } else if (this.tutPhase === 1) {
      // Advance when player fires, clears enemies, or timeout
      if (this.tutFired || this.enemies.length === 0 || this.tutTimer > 8) {
        this.advanceTutorialPhase();
      }
    } else if (this.tutPhase === 2) {
      if (this.tutTimer > 1.5) {
        this.status = 'playing';
        this.spawnWave(0);
        this.onTutorialPhaseChange?.(-1);
      }
    }
  }

  private advanceTutorialPhase(): void {
    this.tutPhase = (this.tutPhase + 1) as 0 | 1 | 2;
    this.tutTimer = 0;
    this.onTutorialPhaseChange?.(this.tutPhase);

    if (this.tutPhase === 1) {
      this.tutFired = false;
      this.spawnTutorialEnemies();
    }
  }

  // ── Private: render ───────────────────────────────────────────────────────

  private render(): void {
    const { ctx } = this;
    ctx.clearRect(0, 0, W, H);
    ctx.fillStyle = '#000009';
    ctx.fillRect(0, 0, W, H);

    for (const s of this.stars) {
      ctx.fillStyle = 'rgba(255,255,255,0.8)';
      ctx.fillRect(s.x, s.y, 1, 1);
    }

    if (this.status === 'countdown') { this.renderCountdown(); return; }
    if (this.status === 'gameover')  { this.renderGameOver();  return; }
    if (this.status !== 'playing' && this.status !== 'tutorial') return;

    // Particles (behind everything)
    for (const p of this.particles) {
      ctx.globalAlpha = Math.max(0, p.life);
      ctx.fillStyle = p.color;
      ctx.fillRect(p.x - 2, p.y - 2, 4, 4);
    }
    ctx.globalAlpha = 1;

    for (const e of this.enemies)    this.drawEnemy(e.x, e.y);
    for (const p of this.projectiles) this.drawProjectile(p.x, p.y);

    if (this.evadeTimer > 0) {
      ctx.globalAlpha = 0.4 + 0.6 * Math.abs(Math.sin(Date.now() / 40));
    }
    this.drawShip(Math.round(this.shipX), Math.round(this.shipY));
    ctx.globalAlpha = 1;

    // Shield ring (pulsing)
    if (this.shieldActive) {
      ctx.strokeStyle = this.colorTonic;
      ctx.lineWidth = 2;
      ctx.globalAlpha = 0.7 + 0.3 * Math.sin(Date.now() / 200);
      ctx.beginPath();
      ctx.arc(this.shipX, this.shipY, 24, 0, Math.PI * 2);
      ctx.stroke();
      ctx.globalAlpha = 1;
    }

    // Shield absorption flash
    if (this.shieldFlashTimer > 0) {
      ctx.fillStyle = this.colorTonic;
      ctx.globalAlpha = (this.shieldFlashTimer / SHIELD_FLASH_DUR) * 0.45;
      ctx.beginPath();
      ctx.arc(this.shipX, this.shipY, 32, 0, Math.PI * 2);
      ctx.fill();
      ctx.globalAlpha = 1;
    }

    // IV heal: gold screen flash
    if (this.healFlashTimer > 0) {
      ctx.fillStyle = this.colorTonic;
      ctx.globalAlpha = (this.healFlashTimer / 0.5) * 0.22;
      ctx.fillRect(0, 0, W, H);
      ctx.globalAlpha = 1;
    }

    this.renderHUD();
    this.renderWaveLabel();
    if (this.status === 'tutorial') this.renderTutorialOverlay();
  }

  private renderCountdown(): void {
    const { ctx } = this;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillStyle = this.countdownValue === 0 ? this.colorDominant : '#ffffff';
    ctx.font = "80px 'Press Start 2P', monospace";
    ctx.fillText(this.countdownValue > 0 ? String(this.countdownValue) : 'GO!', W / 2, H / 2);
    ctx.textAlign = 'left';
    ctx.textBaseline = 'alphabetic';
  }

  private renderGameOver(): void {
    const { ctx } = this;
    ctx.fillStyle = 'rgba(0,0,0,0.72)';
    ctx.fillRect(0, 0, W, H);

    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';

    ctx.fillStyle = this.colorDominant;
    ctx.font = "40px 'Press Start 2P', monospace";
    ctx.fillText('GAME OVER', W / 2, H / 2 - 70);

    ctx.fillStyle = '#ffffff';
    ctx.font = "16px 'Press Start 2P', monospace";
    ctx.fillText(`SCORE  ${this.score}`, W / 2, H / 2 - 10);

    // PLAY AGAIN button — hitbox mirrors handleClick()
    ctx.fillStyle = this.colorDominant;
    ctx.fillRect(290, 250, 220, 40);
    ctx.fillStyle = '#0d0d1a';
    ctx.font = "10px 'Press Start 2P', monospace";
    ctx.fillText('PLAY AGAIN', W / 2, 270);

    ctx.textAlign = 'left';
    ctx.textBaseline = 'alphabetic';
  }

  private renderHUD(): void {
    const { ctx } = this;
    // Hull: 3 mini ship icons top-left
    for (let i = 0; i < 3; i++) {
      ctx.globalAlpha = i < this.hull ? 1 : 0.2;
      this.drawShipIcon(12 + i * 24, 16);
    }
    ctx.globalAlpha = 1;
    ctx.font = "8px 'Press Start 2P', monospace";
    // Score top-right
    ctx.fillStyle = '#aaaaaa';
    ctx.textAlign = 'right';
    ctx.fillText(String(this.score).padStart(6, '0'), W - 10, 20);
    // Key indicator below score
    if (this.selectedKey) {
      ctx.fillStyle = this.colorTonic;
      ctx.fillText(this.selectedKey.name.toUpperCase(), W - 10, 34);
    }
    ctx.textAlign = 'left';
  }

  private renderWaveLabel(): void {
    if (this.waveLabelTimer <= 0 || !this.waveLabel) return;
    const { ctx } = this;
    const fadeIn  = Math.min(1, (WAVE_LABEL_DUR - this.waveLabelTimer) * 4);
    const fadeOut = Math.min(1, this.waveLabelTimer * 2);
    ctx.globalAlpha = Math.min(fadeIn, fadeOut);
    ctx.fillStyle = '#ffffff';
    ctx.font = "8px 'Press Start 2P', monospace";
    ctx.textAlign = 'center';
    ctx.fillText(this.waveLabel, W / 2, 22);
    ctx.textAlign = 'left';
    ctx.globalAlpha = 1;
  }

  // ── Private: drawing ──────────────────────────────────────────────────────

  private drawShip(cx: number, cy: number): void {
    const { ctx } = this;
    ctx.fillStyle = '#99ccff';
    ctx.fillRect(cx - 12, cy - 5, 22, 10); // body
    ctx.fillRect(cx + 10, cy - 3, 10, 6);  // nose
    ctx.fillStyle = '#223355';
    ctx.fillRect(cx - 2, cy - 3, 8, 6);    // cockpit
    ctx.fillStyle = '#6699cc';
    ctx.fillRect(cx - 18, cy - 10, 8, 6);  // top fin
    ctx.fillRect(cx - 18, cy + 4, 8, 6);   // bottom fin
    ctx.fillStyle = this.colorDominant;
    ctx.fillRect(cx - 16, cy - 2, 5, 4);   // engine glow
  }

  private drawShipIcon(cx: number, cy: number): void {
    const { ctx } = this;
    ctx.fillStyle = '#99ccff';
    ctx.fillRect(cx - 7, cy - 3, 14, 6);
    ctx.fillRect(cx + 7, cy - 2, 5, 4);
    ctx.fillRect(cx - 11, cy - 6, 5, 4);
    ctx.fillRect(cx - 11, cy + 2, 5, 4);
  }

  private drawEnemy(x: number, y: number): void {
    const { ctx } = this;
    ctx.fillStyle = '#cc3333';
    ctx.fillRect(x, y, ENEMY_W, ENEMY_H);
    ctx.fillStyle = '#ff6666';
    ctx.fillRect(x + 3, y + 3, 4, 4);      // left eye
    ctx.fillRect(x + 13, y + 3, 4, 4);     // right eye
    ctx.fillStyle = '#992222';
    ctx.fillRect(x + 4, y - 4, 2, 4);      // left antenna
    ctx.fillRect(x + 14, y - 4, 2, 4);     // right antenna
    for (let i = 0; i < 3; i++) {
      ctx.fillRect(x + 3 + i * 5, y + 9, 3, 2); // mouth grill
    }
  }

  private drawProjectile(x: number, y: number): void {
    const { ctx } = this;
    const grad = ctx.createLinearGradient(x, 0, x + PROJ_W, 0);
    grad.addColorStop(0, 'transparent');
    grad.addColorStop(1, this.colorDominant);
    ctx.fillStyle = grad;
    ctx.fillRect(x, y + 1, PROJ_W, PROJ_H - 2);
    ctx.fillStyle = '#ffffff';
    ctx.fillRect(x + PROJ_W - 4, y + 2, 4, PROJ_H - 4); // bright tip
  }

  // ── Private: spawning ─────────────────────────────────────────────────────

  private snapToNearestEnemyRow(): void {
    const candidates = this.enemies
      .filter(e => !e.dead && e.x > this.shipX)
      .map(e => e.y + ENEMY_H / 2);
    if (candidates.length === 0) return;
    const rowYs = [...new Set(candidates)];
    let nearest = rowYs[0]!;
    for (const y of rowYs) {
      if (Math.abs(y - this.shipY) < Math.abs(nearest - this.shipY)) nearest = y;
    }
    this.shipY   = nearest;
    this.targetY = nearest;
  }

  private spawnProjectile(): void {
    this.projectiles.push({
      x: this.shipX + 12,
      y: this.shipY - PROJ_H / 2,
      dead: false,
    });
  }

  private spawnParticles(cx: number, cy: number): void {
    const count = 8;
    for (let i = 0; i < count; i++) {
      const angle = (Math.PI * 2 * i) / count + Math.random() * 0.4;
      const speed = 50 + Math.random() * 90;
      this.particles.push({
        x: cx, y: cy,
        vx: Math.cos(angle) * speed,
        vy: Math.sin(angle) * speed,
        life: 1,
        color: this.colorDominant,
      });
    }
  }

  private startTutorial(): void {
    this.status = 'tutorial';
    this.tutPhase = 0;
    this.tutTimer = 0;
    this.tutFired = false;
    this.enemies = [];
    this.projectiles = [];
    // Place target on opposite side of canvas from ship start position
    this.tutTargetY = H * 0.25;
    this.onTutorialPhaseChange?.(0);
  }

  private spawnTutorialEnemies(): void {
    this.enemySpeed = 18;
    const rowY = this.shipY - ENEMY_H / 2;
    const startX = W * 0.55;
    for (let col = 0; col < 4; col++) {
      this.enemies.push({
        x: startX + col * ENEMY_COL_SPACING,
        y: rowY,
        dead: false,
      });
    }
  }

  private renderTutorialOverlay(): void {
    const { ctx } = this;
    const pulse = 0.6 + 0.4 * Math.abs(Math.sin(Date.now() / 600));

    if (this.tutPhase === 0) {
      // Draw target reticle
      const tx = W * 0.65;
      const ty = this.tutTargetY;
      ctx.strokeStyle = this.colorTonic;
      ctx.lineWidth = 2;
      ctx.globalAlpha = pulse;
      ctx.beginPath();
      ctx.arc(tx, ty, 18, 0, Math.PI * 2);
      ctx.stroke();
      // Crosshair ticks
      ctx.beginPath();
      ctx.moveTo(tx - 24, ty); ctx.lineTo(tx - 14, ty);
      ctx.moveTo(tx + 14, ty); ctx.lineTo(tx + 24, ty);
      ctx.moveTo(tx, ty - 24); ctx.lineTo(tx, ty - 14);
      ctx.moveTo(tx, ty + 14); ctx.lineTo(tx, ty + 24);
      ctx.stroke();
      ctx.globalAlpha = 1;

      // Dashed line from ship to target
      ctx.setLineDash([4, 6]);
      ctx.strokeStyle = this.colorTonic;
      ctx.globalAlpha = 0.3;
      ctx.beginPath();
      ctx.moveTo(this.shipX + 20, this.shipY);
      ctx.lineTo(tx - 20, ty);
      ctx.stroke();
      ctx.setLineDash([]);
      ctx.globalAlpha = 1;

      // Direction arrow on ship
      const dir = ty < this.shipY ? -1 : 1;
      ctx.fillStyle = this.colorTonic;
      ctx.globalAlpha = pulse;
      const ax = this.shipX + 4;
      const ay = this.shipY + dir * 18;
      ctx.beginPath();
      ctx.moveTo(ax,     ay + dir * 8);
      ctx.lineTo(ax - 6, ay);
      ctx.lineTo(ax + 6, ay);
      ctx.closePath();
      ctx.fill();
      ctx.globalAlpha = 1;

      this.drawInstructionBox(
        W / 2, H - 50,
        ['STEER YOUR SHIP', 'HIGHER NOTE = UP  /  LOWER NOTE = DOWN'],
      );
    } else if (this.tutPhase === 1) {
      const vChordName = this.selectedKey?.diatonicChords[4]?.chord.name ?? 'V chord';
      this.drawInstructionBox(
        W / 2, H - 50,
        [`V CHORD → FIRE`, `PLAY ${vChordName.toUpperCase()}`],
      );
    } else if (this.tutPhase === 2) {
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.font = "32px 'Press Start 2P', monospace";
      ctx.fillStyle = this.colorDominant;
      ctx.globalAlpha = pulse;
      ctx.fillText('READY!', W / 2, H / 2);
      ctx.globalAlpha = 1;
      ctx.textAlign = 'left';
      ctx.textBaseline = 'alphabetic';
    }
  }

  private drawInstructionBox(cx: number, cy: number, lines: string[]): void {
    const { ctx } = this;
    const pad = 14;
    const lineH = 18;
    const boxH = lines.length * lineH + pad * 2;
    const boxW = 440;
    const x = cx - boxW / 2;
    const y = cy - boxH / 2;

    ctx.fillStyle = 'rgba(0,0,9,0.82)';
    ctx.fillRect(x, y, boxW, boxH);
    ctx.strokeStyle = this.colorTonic;
    ctx.lineWidth = 1;
    ctx.strokeRect(x, y, boxW, boxH);

    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    lines.forEach((line, i) => {
      ctx.font = i === 0
        ? "10px 'Press Start 2P', monospace"
        : "7px 'Press Start 2P', monospace";
      ctx.fillStyle = i === 0 ? '#ffffff' : '#888888';
      ctx.fillText(line, cx, y + pad + lineH * i + lineH / 2);
    });
    ctx.textAlign = 'left';
    ctx.textBaseline = 'alphabetic';
  }

  private spawnWave(idx: number): void {
    const cycle = Math.floor(idx / WAVES.length);
    const def   = WAVES[idx % WAVES.length];
    if (!def) return;

    this.enemySpeed  = def.speed * (1 + cycle * 0.2);
    this.waveLabel   = def.label;
    this.waveLabelTimer = WAVE_LABEL_DUR;
    this.enemies     = [];

    for (let row = 0; row < def.rows; row++) {
      for (let col = 0; col < def.cols; col++) {
        this.enemies.push({
          x: W + 50 + col * ENEMY_COL_SPACING,
          y: ENEMY_START_Y + row * ENEMY_ROW_SPACING,
          dead: false,
        });
      }
    }
  }
}
