let audioCtx: AudioContext | null = null;
let analyser: AnalyserNode | null = null;
let stream: MediaStream | null = null;
let rafId: number | null = null;

export async function startListening(onFrame: () => void, deviceId?: string): Promise<void> {
  if (audioCtx) return;
  const audioConstraints: MediaTrackConstraints = {
    echoCancellation: false,
    noiseSuppression: false,
    autoGainControl: false,
  };
  if (deviceId !== undefined) audioConstraints.deviceId = { exact: deviceId };
  stream = await navigator.mediaDevices.getUserMedia({ audio: audioConstraints, video: false });
  audioCtx = new AudioContext();
  analyser = audioCtx.createAnalyser();
  analyser.fftSize = 8192;
  analyser.smoothingTimeConstant = 0.8;
  const source = audioCtx.createMediaStreamSource(stream);
  if (source.channelCount > 1) {
    const splitter = audioCtx.createChannelSplitter(source.channelCount);
    source.connect(splitter);
    splitter.connect(analyser, 0);
  } else {
    source.connect(analyser);
  }

  function loop(): void {
    onFrame();
    rafId = requestAnimationFrame(loop);
  }
  rafId = requestAnimationFrame(loop);
}

export function stopListening(): void {
  if (rafId !== null) { cancelAnimationFrame(rafId); rafId = null; }
  analyser?.disconnect();
  analyser = null;
  stream?.getTracks().forEach(t => t.stop());
  stream = null;
  void audioCtx?.close();
  audioCtx = null;
}

export function getAnalyser(): AnalyserNode | null { return analyser; }
export function getSampleRate(): number { return audioCtx?.sampleRate ?? 44100; }
export function isListening(): boolean { return audioCtx !== null; }
